window.BT_INDEX={"docs":[{"file":"01-overview.html","num":"01","title":"Overview"},{"file":"02-requirements.html","num":"02","title":"Requirements"},{"file":"03-target-architecture.html","num":"03","title":"Target architecture"},{"file":"04-accounts-access-and-operations.html","num":"04","title":"Accounts, access & operations"},{"file":"05-data-and-brokers.html","num":"05","title":"Data & brokers"},{"file":"06-instruments-and-baskets.html","num":"06","title":"Instruments & baskets"},{"file":"07-strategies.html","num":"07","title":"Strategies"},{"file":"08-exits-and-risk.html","num":"08","title":"Exits & risk"},{"file":"09-learning-engine.html","num":"09","title":"Learning engine"},{"file":"10-trade-selection.html","num":"10","title":"Trade selection"},{"file":"11-strategy-lab.html","num":"11","title":"Strategy Lab"},{"file":"12-portfolio-monitoring.html","num":"12","title":"Portfolio monitoring"},{"file":"13-reports-and-ui.html","num":"13","title":"Reports & UI"},{"file":"14-ai-assistant.html","num":"14","title":"AI assistant"},{"file":"15-smart-insights-and-automation.html","num":"15","title":"Smart insights & automation"},{"file":"16-configuration.html","num":"16","title":"Configuration"},{"file":"17-deployment-and-operations.html","num":"17","title":"Deployment & operations"},{"file":"18-roadmap.html","num":"18","title":"Roadmap"},{"file":"19-risks-and-compliance.html","num":"19","title":"Risks & compliance"},{"file":"20-extended-modules.html","num":"20","title":"Extended modules"},{"file":"21-glossary.html","num":"21","title":"Glossary"}],"sections":[{"d":0,"h":"1. What xDrishti is","a":"1-what-xdrishti-is","t":"Name: xDrishti — from Sanskrit drishti (दृष्टि), \"vision, insight\": seeing where your edge is, and where it is not. Short forms: xd (CLI), xd- (containers), XDrishti. (.NET projects), xdrishti (database, Keychain paths). A personal, self-learning trade-planning and portfolio-monitoring system for Indian markets (NSE), running entirely on your Mac in Podman containers. Data: your 1-minute CSV files bootstrap history; the Dhan Data API keeps every tracked instrument up to date after market close and streams live prices only for what you're actively trading or holding . All timeframes (5m … 1h, 1D, 1W, 1M) are aggregated from 1-minute bars. Every evening it: 1. fetches the day's 1-minute data for all tracked instruments and aggregates all timeframes, 2. syncs your broker accounts and grades how previous recommendations played out, 3. updates what it has learned about every setup cell (strategy × timeframe × side × style × exit × regime), 4. scans your baskets (e.g. MyChoice, Best stocks) for tomorrow's candidate trades, 5. estimates each candidate's probability of success and expected reward (in R-multiples), 6. keeps only the best few that fit your risk limits (e.g. max 3 new entries), sized per broker account, 7. publishes a next-day trade plan with entry trigger, stop, exit method, size and reasons. At any time you can: - add your broker accounts and choose what each is used for (data, trading, portfolio), - review and approve the proposed next-day trades and AI suggestions (nothing is armed without you), - manage the instruments you work on and group them into baskets , - monitor your portfolio across accounts — when each trade was added, return %, XIRR , total value — grouped by basket, account, strategy or sector, - evaluate results by basket, by instrument, by individual trade or across all trades , - submit your own strategies in the Strategy Lab and get an honest, tested verdict. You execute (or skip) the trades. The system learns from every outcome."},{"d":0,"h":"2. Core principles","a":"2-core-principles","t":"Principle Consequence 1 Predict whether a setup works, not where price goes Every output is a conditional trade plan with a probability and expected value 2 The setup cell is the unit of learning Exit methods (1:2, 1:3, trailing, pyramiding…) are learned per cell and fitted per trade 3 Rules generate, ML filters, risk rules decide Transparent strategies → calibrated ML probability → deterministic portfolio selection 4 LLM is an analyst, never the trader All numbers come from the deterministic engine; LLM explains, answers, drafts 5 Every recommendation is graded Including rejected candidates — proves the selector adds value 6 Configuration over code Instruments, baskets, timeframes, strategies, exits, limits, accounts — all configurable 7 Honest evaluation Walk-forward out-of-sample only, costs always on, paper stage before live 8 Single code path Backtest, Strategy Lab, nightly scan and grading run the same engine code 9 One source of bars Everything aggregates from 1-minute data (CSV or Dhan) with the same rules 10 Live only where it matters Real-time data only for the active set; everything else end-of-day 11 Local and cheap No cloud dependency; ≈ ₹590/month running cost (Dhan Data API)"},{"d":0,"h":"3. Trading styles","a":"3-trading-styles","t":"Style Entry timeframes Holding Forced exit Intraday 5m, 10m, 15m, 30m, 1h Same session Square-off time (e.g. 15:15) Swing 1h, 1D 1–5 sessions End of session N (N ≤ 5) Long-term holdings — Your choice Not managed by system exits (monitored in the portfolio) Both BUY and SELL. Overnight shorts use futures (cash shorts can't be carried overnight in India)."},{"d":0,"h":"4. Fixed decisions","a":"4-fixed-decisions","t":"Topic Decision Use Personal only — one user, only your own broker accounts; no recommendations to others Market NSE: cash stocks + index/stock futures; options in a later phase Historical data Your 1-minute CSV files + Dhan historical API for gaps Market-data API Dhan Data API only (EOD for tracked instruments, live for the active set) Accounts Multiple accounts (Dhan; Upstox later), each with roles : Data · Trading · Portfolio — one account can hold several; exactly one primary Data account Access Login required (username + password; password re-entry for sensitive actions); single owner; every screen and API protected Operating model Configure once, services run it — background services do the work whether or not you're logged in Insights Pre-trade checklist, portfolio Action center per account, price alerts, data quality gate, report auto-insights Learning visibility & autonomy Learning screen : progress vs a frozen-model counterfactual, lessons (problem → fix → result), plan-vs-actual execution gap, tweak & re-run experiments; smart rules (no-trade days, equity-curve throttle, meta-labelling, learned entry windows, correlation-aware plan); grading on real fills; automatic loss tags; weekly digest; autonomy levels with auto-approval so you only review what matters Decisions Human in the loop — system/AI propose next-day tickets and instrument/basket suggestions; you approve, modify or reject Instruments Master list → tracked instruments → baskets (manual, rule-based, system) Portfolio Holdings, positions & trade history from Dhan + CSV/manual; FIFO lots; XIRR ; buckets Execution v1 manual (system auto-journals your fills); assisted → semi-auto → auto in a later phase Frontend React (TypeScript) Backend .NET (ASP.NET Core, modular monolith) Database PostgreSQL with TimescaleDB extension ML ML.NET inside the .NET solution — no Python LLM Local open model in a GPU-enabled Podman container; optional Hermes Agent front-end after PoC Deployment Podman Desktop on Apple M4 Pro / 48 GB; no cloud Full rationale: 03-target-architecture.md."},{"d":0,"h":"5. Decisions","a":"5-decisions","t":"Recorded 2026-10-09 (story P0-12). Numbers and names below are working values: capital, accounts and baskets are entered in the application (ADR 0002), never in the repository. Question Decision Status Q1 CSV format — one sample file to set up the import profile (column names, timestamp format, bar start or end, raw or adjusted prices) Not provided yet Open — story P0-14 stays blocked; needed before P1-07 Q2 Trading capital and risk per trade Defaults stay: 0.5% per trade, 1.5% daily loss limit (doc 16). Capital is entered per account in the accounts wizard Decided in P1-16 Q3 Initial baskets and their purpose Working names as configured in doc 16: Best stocks (intraday + swing), MyChoice (intraday), MyLongTerm (swing, BUY only); baskets are created in the app Decided in P1-15 (baskets are app data, not a blocker) Q4 Several accounts: replicate or distribute Replicate (default; allocation.mode stays configurable) Decided Q5 Portfolio history depth Start with the Dhan trade-history window ; import older lots from CSV / contract notes later (P2-03) Decided Q6 ISP static IP Later — needed only before automated orders (P12); revisit at the P11 exit Decided Q7 Repository hosting Local-only git; no remote or CI dependence for now; back the code up (doc 17 §1) Decided Q8 Podman machine size Keep 10 CPUs / 24 GB / 120 GB — verified by the xd-llm benchmark (P0-15, ADR 0005); revisit before tick data (P13) Decided, verified"},{"d":0,"h":"6. Definition of success (v1)","a":"6-definition-of-success-v1","t":"- Your CSV history imported; all tracked instruments updated every evening; all timeframes consistent. - Portfolio shows every holding/trade with added date, return %, XIRR and value, grouped by bucket/basket/account. - Nightly run completes unattended in < 30 min and publishes ≤ max new entries per day tickets per account. - Each ticket: symbol, side, style, timeframe, trigger & validity window, stop, exit policy, size, P(win), expected R, plain-English reason. - Results viewable for any date range by all trades / basket / instrument / trade / strategy / account. - Your own strategies tested via the Strategy Lab without code changes. - After ≥ 12 weeks of paper trading: positive expectancy after costs, consistent with backtest expectations."},{"d":0,"h":"7. Document map","a":"7-document-map","t":"Doc Content 02 Requirements Functional & non-functional requirements 03 Target architecture Tech stack, components, solution structure, data model, APIs 04 Accounts, access & operations Account roles, login, service-level operation, human-in-the-loop approvals 05 Data & brokers CSV import, aggregation, Dhan EOD & live (active set), storage, quality 06 Instruments & baskets Master list, tracked instruments, baskets, evaluation lenses 07 Strategies Strategy anatomy, conditional plans, library, features, regimes 08 Exits & risk R-multiples, exit policies, pyramiding, sizing, limits, costs 09 Learning engine Cell stats, meta-model, walk-forward, drift, hypothesis loop 10 Trade selection From N candidates to top 3, per-account allocation 11 Strategy Lab Runtime strategy rules, testing pipeline, verdict reports 12 Portfolio monitoring Holdings, trades, returns, XIRR, buckets, live values 13 Reports & UI React screens and report catalogue 14 AI assistant Local LLM roles, tools, guardrails, Hermes Agent decision 15 Smart insights & automation Pre-trade checklist, portfolio Action center, alerts, data quality gate, auto-insights 16 Configuration Full trading config reference 17 Deployment & operations Podman topology, secrets, backups, costs 18 Roadmap Phases and exit criteria 19 Risks & compliance Pitfalls, safeguards, SEBI notes 20 Extended modules Auto-execution, options, tick/depth data, fundamentals 21 Glossary Terms"},{"d":1,"h":"1. Functional requirements","a":"1-functional-requirements","t":""},{"d":1,"h":"FR-1 Data","a":"fr-1-data","t":"1. Import 1-minute OHLCV from CSV files (upload, watched folder, CLI) using saved column-mapping profiles; preview, validate, upsert with source precedence, report and undo per import job. 2. Aggregate 1-minute bars into 5m/10m/15m/30m/1h (09:15-aligned), 1D, 1W, 1M with identical rules for CSV and Dhan data; refresh after every import/fetch. 3. End-of-day fetch from the Dhan Data API for all tracked instruments (today's 1-minute + daily), gap backfill, instrument master refresh. 4. Live data only for the active set (open positions, armed tickets, context indices, optional pinned basket) via Dhan WebSocket; holdings via quote polling; live bars replaced by official bars at EOD. 5. Adjust for splits/bonus; keep raw prices for tradable levels. 6. Store context: indices, India VIX, breadth, sector indices, calendar, expiries, lot sizes, corporate actions. 7. Data-quality checks; fail closed (no plan) on critical failures. 8. Data quality window : per-instrument validation of completeness, bar sanity, spikes, stored-vs-recomputed aggregates and derived-vs-official daily, with inspect, repair and run history."},{"d":1,"h":"FR-2 Instruments & baskets","a":"fr-2-instruments-baskets","t":"1. Master list from Dhan's instrument master, searchable and filterable. 2. Tracked instruments: add/remove (single or bulk); activation triggers history backfill (CSV, then Dhan). 3. Baskets: manual, rule-based (dynamic) and system baskets; an instrument can be in many baskets; membership history kept. 4. Baskets define scopes for scans, Strategy Lab tests, reports, portfolio grouping and live watch. 5. Evaluation lenses: all trades, by basket, by instrument, by individual trade, by strategy, by account."},{"d":1,"h":"FR-3 Brokers & accounts","a":"fr-3-brokers-accounts","t":"1. Pluggable broker adapters behind common interfaces (Dhan in v1; Upstox and others later). 2. Any number of accounts, each with its own risk profile, styles, instruments and mode. 3. Each account has one or more roles — Data, Trading, Portfolio; exactly one primary Data account (optional standby with automatic failover); role changes audited and protected by password re-entry. 4. Read funds, positions, holdings, trade history and ledger per account (read-only in v1). 5. Auto-journal: match broker fills to recommendations. 6. Token lifecycle per account (Dhan 24 h tokens via API key/secret)."},{"d":1,"h":"FR-3b Access & operating model","a":"fr-3b-access-operating-model","t":"1. Login required for every screen and API (username + password; no second factor — personal, LAN-only), idle timeout, lockout, password re-entry for sensitive actions. 2. All configuration and actions are persisted as desired state and executed by background services under a service identity — independent of any logged-in session or open browser. 3. Missed schedules (machine asleep) are caught up on start; jobs are idempotent and retried. 4. Services screen: status, schedule, last/next run, run now, pause/resume. 4. Service schedules editable in the UI (type, time, days, window, interval, run-after, retries, timeout, catch-up, parameters) with dependency & timing validation; automatic data failover to a standby account."},{"d":1,"h":"FR-3c Human-in-the-loop decisions","a":"fr-3c-human-in-the-loop-decisions","t":"1. Next-day tickets are proposed ; you approve, modify (re-validated) or reject; unreviewed tickets lapse at the review cutoff; only approved tickets are armed. 2. AI/engine suggestions (track instrument, basket membership, promotions, config changes) go to an inbox for approval, with reasons and expiry. 3. Reports compare system proposals vs your decisions. 4. Pre-trade checklist per ticket (data quality, holdings conflict, sector exposure, event risk). 5. Optional auto-approval at the cutoff for tickets above a probability threshold with every check passing (autonomy level supervised or higher); auto-approved tickets are marked and audited."},{"d":1,"h":"FR-4 Portfolio monitoring","a":"fr-4-portfolio-monitoring","t":"1. Build transactions, FIFO lots and positions from broker trade history, CSV imports and manual entries. 2. Per position/trade: added date, days held, quantity, average cost, LTP, value, unrealised/realised P&L, return %, day change, XIRR , CAGR, weight. 3. Per group (bucket, basket, account, strategy, sector, total): invested, value, returns, XIRR , benchmark XIRR and alpha, drawdown. 4. Portfolio buckets (exclusive, additive) and basket lens (overlapping). 5. Live values during market hours; daily valuation snapshots; alerts. 6. Per-account tiles and an Action center of positions needing a decision (rules in doc 15); price alerts evaluated by services."},{"d":1,"h":"FR-5 Strategies & signals","a":"fr-5-strategies-signals","t":"1. Strategies declare timeframes, sides, styles, setup, trigger, entry, initial stop, filters, invalidation. 2. Multi-timeframe filters (bias from higher timeframe). 3. Output = conditional trade plans (trigger + validity window + invalidation)."},{"d":1,"h":"FR-6 Exits & risk","a":"fr-6-exits-risk","t":"1. Exit policy library: fixed R:R, partials, ATR/structure/EMA trailing, pyramiding, time stop, session exit, max hold (≤ 5 sessions), event exit. 2. Exit chosen per setup cell (walk-forward), fitted per trade (volatility, structure, obstacles). 3. Fixed-fractional sizing with lot rounding; portfolio and per-account limits."},{"d":1,"h":"FR-7 Learning","a":"fr-7-learning","t":"1. Walk-forward backtest of every strategy × timeframe × side × exit policy. 2. Per-cell statistics (Bayesian, recency-weighted, regime-conditioned). 3. Calibrated meta-model P(success) per candidate; must beat baselines. 4. Daily grading of primary, reserve and rejected recommendations. 5. Drift detection, auto-pause, re-qualification; cell lifecycle. 6. Hypothesis loop: one-variable experiments, tested offline and in shadow before promotion. 7. Learning changelog explaining every automatic change. 8. Learn from actual executions : grade on fills, decompose plan-vs-actual gap, per-liquidity slippage model, capacity score (doc 09 §9). 9. Lessons for every detected problem (what went wrong → diagnosis → fix → result) with revert (doc 09 §10). 10. Learning screen showing progress against a frozen-model counterfactual, learning health, setups and lessons (doc 09 §11). 11. Tweak & re-run : change learning knobs and replay walk-forward with honest comparison rules; shadow → apply with password; automatic rollback (doc 09 §12). 12. Autonomy levels (advisory / supervised / autonomous within limits) to reduce manual work while risk increases, new strategies, live execution and account changes always need you (doc 09 §13). 13. Smart rules learned from history and applied nightly: market gate (no-trade / reduced days), equity-curve throttle, meta-labelling (take / size), learned entry windows, correlation-aware plan (doc 09 §14). 14. Automatic loss tags on every losing trade, linked to lessons; weekly learning digest ."},{"d":1,"h":"FR-8 Selection & plan","a":"fr-8-selection-plan","t":"1. Eligibility filters, duplicate merge (confluence), ranking by conservative expected R. 2. Constraints: max new entries/day, max open positions, heat, sector, correlation, net exposure, loss limits. 3. Per-account allocation (replicate or distribute) and sizing. 4. Primary plan + reserve list; optional pre-open gap validation."},{"d":1,"h":"FR-9 Strategy Lab","a":"fr-9-strategy-lab","t":"1. Submit strategies at runtime: rules file, form, plain English (LLM-drafted, user-confirmed), C plugin; choose a basket (or instruments) as the test universe. 2. Validate (schema, look-ahead lint), quick test, full walk-forward test, robustness checks. 3. Verdict (PASS / MARGINAL / FAIL) with reasons, KPIs, charts, comparisons, trade replay. 4. Test ledger with multiple-testing-adjusted thresholds; promotion only through paper stage."},{"d":1,"h":"FR-10 Reports & UI","a":"fr-10-reports-ui","t":"1. Next-day plan per account, journal, portfolio, performance for any date range with lenses and filters. 2. Reports landing overview with auto-insights; multi-basket comparison; pivot builder. 3. Visual analytics: equity/drawdown, heatmaps, exit comparison, MAE/MFE, calibration, selector effectiveness, Monte Carlo, learning changelog, cell lifecycle, data quality, discipline. 4. Config editor with validation, diff and versioned activation. 5. Exports: PDF/HTML/CSV. 6. Responsive layout from 360 px phones to 4K / ultrawide monitors."},{"d":1,"h":"FR-11 AI assistant","a":"fr-11-ai-assistant","t":"1. Daily briefing and weekly review written from structured data. 2. Natural-language questions over data via read-only tools; numbers only from tool results. 3. Strategy drafting for the Strategy Lab; hypothesis proposals."},{"d":1,"h":"2. Non-functional requirements","a":"2-non-functional-requirements","t":"ID Requirement NFR-1 Fully local on macOS (Apple Silicon) in Podman containers; no cloud dependency NFR-2 EOD fetch + nightly cycle < 45 min for 200 tracked instruments; full re-learn < 4 h; CSV import ≥ 1 M rows/min NFR-2b Live updates < 2 s from tick to screen for the active set; live feed limited to the active set NFR-3 Reproducible: any plan/test regenerable from data snapshot + config version + model version NFR-4 No look-ahead: enforced by engine design and automated tests NFR-5 Explainable: reasons and statistics attached to every recommendation NFR-6 Config validated on load (JSON Schema); invalid config never activates NFR-7 Fail closed: incomplete data or failed stage ⇒ no plan, clear error NFR-8 Secrets never in code, config, logs or LLM prompts NFR-9 Personal use: single owner; login (password); LAN-only access; audit of logins, changes and approvals NFR-11 Services keep running when no one is logged in; UI is only a control plane NFR-12 Responsive UI from 360 px phones to 3840 px monitors with no horizontal page scroll NFR-10 Running cost ≈ ₹590/month (Dhan Data API); all software open source / free"},{"d":2,"h":"1. Architecture at a glance","a":"1-architecture-at-a-glance","t":"Style: a .NET modular monolith (one codebase, clear module boundaries) deployed as a few containers, with a React single-page app, PostgreSQL + TimescaleDB as the only database, ML.NET for machine learning (no Python), and a local LLM — all on Podman Desktop. Why a modular monolith (not microservices): one developer, one machine, shared engine code across backtest / Strategy Lab / nightly scan / grading. Modules can be split into services later if ever needed."},{"d":2,"h":"2. Technology decisions","a":"2-technology-decisions","t":""},{"d":2,"h":"2.1 Frontend — React","a":"21-frontend-react","t":"Concern Choice Reason Framework React 19 + TypeScript + Vite Your choice; fast dev build UI kit MUI (Material UI) + MUI X Data Grid (community) Mature components, dense data tables Price charts TradingView Lightweight Charts (open source) Candles with entry/stop/target/trail overlays, trade replay Analytics charts Apache ECharts (echarts-for-react) Heatmaps, calendar, Monte Carlo fans, scatter, large data Server state TanStack Query Caching, refetch, pagination Routing React Router — Forms React Hook Form + Zod Strategy form builder, config forms Code editor Monaco + monaco-yaml with JSON Schema Strategy rules & config editing with live validation Real-time @microsoft/signalr Live prices & P&L for the active set, job progress, notifications File upload react-dropzone + chunked upload CSV imports with preview API client Generated from OpenAPI (orval) Typed client, no hand-written DTOs Tests Vitest + Testing Library; Playwright for E2E —"},{"d":2,"h":"2.2 Backend — .NET","a":"22-backend-net","t":"Concern Choice Reason Runtime .NET 10 (LTS) , C Your choice; LTS support window Web ASP.NET Core (Minimal API endpoint groups), OpenAPI Lightweight, typed Real-time SignalR Progress & notifications to React Data access EF Core + Npgsql for domain tables; Npgsql binary COPY / Dapper for bulk bars EF for productivity, raw speed for time series Background jobs Hangfire + Hangfire.PostgreSql Cron schedules, retries, queues, built-in dashboard; no extra infra Validation FluentValidation; JsonSchema.Net for YAML config/strategy One schema shared with the React editor YAML YamlDotNet Trading config & strategy rules Strategy DSL Own parser (Superpower) → compiled LINQ expression trees Safe (no eval), fast, look-ahead-checked Indicators Own streaming implementations (cross-checked against Skender.Stock.Indicators) Point-in-time control, speed Numerics MathNet.Numerics Statistics, Monte Carlo, Bayesian updates; own XIRR solver (Newton–Raphson + bisection) CSV parsing Sep or CsvHelper (streaming) + Npgsql binary COPY Fast bulk import of 1-minute files Live feed System.Net.WebSockets client + binary packet parser (Dhan little-endian format) Active-set streaming in xd-feed Machine learning ML.NET (LightGBM / FastTree trainers, PAV calibration, feature contributions) Train and score in-process; one language, one code path LLM client Microsoft.Extensions.AI (OpenAI-compatible) Tool calling against the local model MCP server ModelContextProtocol C SDK Read-only tools for the assistant / Hermes HTTP resilience Microsoft.Extensions.Http.Resilience (Polly) Broker API retries, rate limits Auth ASP.NET Core Identity (single user, password) Personal use; cookie auth CLI System.CommandLine (xd tool) Strategy Lab and ops from terminal Logging/telemetry Serilog → Seq ; OpenTelemetry metrics/traces Local, searchable logs Tests xUnit, Testcontainers (real Postgres/Timescale), Verify snapshots Engine correctness & look-ahead tests"},{"d":2,"h":"2.3 Data — PostgreSQL","a":"23-data-postgresql","t":"Concern Choice Reason Database PostgreSQL 17+ Your choice Time series TimescaleDB extension (official image) Hypertables + native compression for 1-min bars/ticks; continuous aggregates build 5m/10m/15m/30m/1h bars from 1m with 09:15 alignment; refreshed after CSV imports and EOD fetch Queue Hangfire tables in Postgres; LISTEN/NOTIFY for events No separate broker (Redis/RabbitMQ) needed Analytics Plain SQL + materialised views for report aggregates Single database to back up and query Backups pg dump nightly + restic to external SSD Simple, verifiable Estimated size: 1-min bars for 200 symbols × 8 years ≈ 150 M rows → 5–10 GB with Timescale compression."},{"d":2,"h":"2.4 ML — ML.NET only (no Python)","a":"24-ml-mlnet-only-no-python","t":"Our ML need is modest and well-defined: a binary classifier on tabular features ( 10⁵–10⁶ rows, 50–150 features) answering \"does this candidate hit target before stop?\", plus calibration and explanations. ML.NET covers all of it: Need ML.NET capability Gradient-boosted trees LightGbm trainer (Microsoft.ML.LightGbm); FastTree (ML.NET's own GBDT) as fallback Baselines LbfgsLogisticRegression, SdcaLogisticRegression Probability calibration Calibrators incl. PAV (isotonic) and Platt; plus own reliability-curve check Per-prediction explanation CalculateFeatureContribution (supported for LightGBM/FastTree/linear models) Global importance Permutation Feature Importance (PFI) Metrics AUC, log-loss, Brier score via evaluation APIs + own walk-forward metrics Persistence Model .zip in the models volume + research.model versions row; champion/challenger = DB pointer Flow: features and triple-barrier labels are computed by the same .NET code used for scanning → a weekly Hangfire job trains, calibrates and validates per walk-forward fold → the model is saved and registered → PredictionEngine/batch transform scores candidates in-process during the nightly run. Why not Python: no second language/runtime, no extra container, no model-export hop, identical feature code for training and scoring. What we give up — exact SHAP values, Optuna-style tuning, notebook ecosystem — is not needed: feature contributions + PFI explain decisions, and the design deliberately avoids heavy tuning (few parameters, plateaus). Platform check (Phase 0 spike): containers on Apple Silicon are linux/arm64. Verify the LightGBM native library loads there (if not, build lib lightgbm.so from source in the worker image); fall back to the managed FastTree trainer otherwise. The model sits behind an IProbabilityModel interface, so the trainer can change without touching Planning or Learning."},{"d":2,"h":"2.5 AI","a":"25-ai","t":"Concern Choice Model server llama.cpp server (pinned RamaLama image) in a container with GPU (libkrun); OpenAI-compatible API; started on demand (ADR 0005) Model Qwen3-30B-A3B at 4-bit (alternate gpt-oss-20b), 16K default / 32K supported context; no separate small model Integration Assistant endpoint in xd-api (Microsoft.Extensions.AI) + xd-mcp read-only tool server Optional Hermes Agent as hardened front-end after PoC (doc 14)"},{"d":2,"h":"2.6 Infrastructure","a":"26-infrastructure","t":"Concern Choice Containers Podman Desktop , libkrun machine (GPU for LLM), compose.yaml with profiles Proxy Caddy — serves the React build, local TLS, routes /api, /hubs, /hangfire Secrets macOS Keychain → Podman secrets → .NET KeyPerFile configuration provider Logs Seq (free single-user) Backups restic → external SSD"},{"d":2,"h":"3. Modules (inside the .NET solution)","a":"3-modules-inside-the-net-solution","t":"Module Responsibility Market Bars, aggregation, context, calendar, corporate actions, data quality Data import CSV profiles, import jobs (preview, validate, upsert, undo), folder watcher Catalog Instrument master, tracked instruments, baskets (manual / rule / system), membership history Live Active-set computation, WebSocket subscriptions, live 1-minute bars, quote polling, live P&L & alerts Brokers Adapters (Dhan in v1; Upstox later; NSE files) implementing IMarketDataProvider, ILiveFeed, IAccountReader, ITokenProvider, (later) IOrderExecutor Portfolio Transactions, FIFO lots, positions, buckets, valuations, returns, XIRR, benchmark, alerts Indicators & Features Streaming indicators, multi-timeframe features, regime labels Strategies Built-in strategies, DSL parser/compiler, plugin host Simulation Event-driven bar-by-bar engine: conditional entries, exits, pyramids, gaps, costs, slippage, MAE/MFE Learning Walk-forward runner, cell stats (Bayesian), exit selection, drift, lifecycle, hypothesis loop, ML.NET training & scoring, execution feedback, lessons, experiments (replay), autonomy rules Planning Scanner, scorer, selector, per-account allocator, pre-open check Trading Accounts, sync, journal, fill matching, outcomes grading, (later) execution Lab Strategy submissions, test runs, verdicts, test ledger Reporting Report queries with lenses (all / basket / instrument / trade / strategy / account), aggregates, exports Assistant LLM chat, tool routing, briefings Workflow Proposals, approvals (plan tickets, suggestions), review cutoff, suggestion inbox, pre-trade checklist Insights Portfolio action-center rules, price alerts, report auto-insights (doc 15) Data quality Validation runs (completeness, sanity, spikes, stored vs recomputed aggregates, derived vs official daily), repairs, quality score Scheduling Service schedules (DB-stored), dependency & timing rules, run-after chains, catch-up, failover Platform Config versions, auth (Identity, password re-entry), audit, notifications, commands, service runs Single code path: Simulation + Strategies + Features are used identically by the Strategy Lab, walk-forward learning, the nightly scanner and the outcome grader."},{"d":2,"h":"4. Repository & solution structure","a":"4-repository-solution-structure","t":"One repository (monorepo) holds the code, configuration, deployment and design material. xDrishti/ ├── backend/ .NET 10 solution │ ├── XDrishti.slnx solution (src/, tests/ folders) │ ├── global.json SDK pin + Microsoft Testing Platform │ ├── Directory.Build.props shared build settings, analyzers, nullable, warnings-as-errors │ ├── Directory.Packages.props central package versions │ ├── Dockerfile multi-stage: targets api, worker (chiseled, non-root) │ ├── contracts/XDrishti.Api.json OpenAPI contract generated at build (source of frontend types) │ ├── src/ │ │ ├── XDrishti.Domain/ entities & value objects: Bar, Instrument, Signal, TradeTicket, RMultiple, Cell… │ │ ├── XDrishti.Application/ use cases, interfaces (ports), pipeline orchestration │ │ ├── XDrishti.Infrastructure/ EF Core, Npgsql COPY, Timescale, secrets, LLM client, model store, default seed │ │ ├── XDrishti.Brokers.Dhan/ REST + WebSocket feed + instrument master │ │ ├── XDrishti.Brokers.Nse/ optional reconciliation files │ │ ├── XDrishti.DataImport/ CSV profiles, parsers, import jobs │ │ ├── XDrishti.Catalog/ instruments, tracked list, baskets │ │ ├── XDrishti.Portfolio/ lots, positions, valuations, XIRR │ │ ├── XDrishti.Indicators/ │ │ ├── XDrishti.Strategies/ built-ins + DSL (parser, compiler, look-ahead lint) + plugin host │ │ ├── XDrishti.Simulation/ │ │ ├── XDrishti.Learning/ cells, meta-model, smart rules, experiments, lessons │ │ ├── XDrishti.Planning/ │ │ ├── XDrishti.Hosting/ shared host defaults: KeyPerFile secrets, Serilog, app info │ │ ├── XDrishti.Api/ host: endpoints, SignalR hubs, auth, OpenAPI; migrate command │ │ ├── XDrishti.Worker/ host: Hangfire server, scheduled services │ │ ├── XDrishti.Mcp/ host: MCP read-only tool server │ │ ├── XDrishti.Cli/ xd command-line tool │ │ ├── XDrishti.Feed/ host: market-hours live feed for the active set (later: depth recorder) │ │ └── XDrishti.Execution/ host (later): order service │ └── tests/ Domain/Application unit, Architecture (layer rules), Api.IntegrationTests (Testcontainers) ├── frontend/ React 19 + TypeScript + Vite + MUI; Dockerfile builds xd-proxy (Caddy + app) │ └── src/{app, features/<name , shared/{api,ui,lib}, theme, test} ├── data/ local runtime data, git-ignored: inbox/ (CSV drop, mounted into xd-worker), exports/, models/ ├── deploy/ compose.yaml (+ compose.dev.yaml), caddy/Caddyfile, db/init, xd-up.sh / xd-down.sh ├── scripts/ check.sh (all gates), gen-api.sh, dev-api.sh, build-docs.sh, serve.sh ├── docs/ │ ├── design/ these design documents (Markdown source of truth) │ ├── adr/ architecture decision records │ ├── engineering/ engineering standards (SOLID, modularity, testing, performance, DoD) │ ├── prototype/ clickable UX prototype (reference for the React app) │ └── site/ generated HTML version of docs/design └── tools/ docs-site builder, prototype vendoring Trading configuration and strategies are not repository folders : they live in the database (versioned, validated, audited) and are managed in the app; built-in defaults ship inside the backend and are seeded on first start (ADR 0002). Dependency rule: Domain ← Application ← (Infrastructure, Brokers. , engine modules) ← hosts. Engine modules (Indicators, Strategies, Simulation, Learning, Planning) have no I/O dependencies — they're pure and fully unit-testable."},{"d":2,"h":"5. Data model (PostgreSQL schemas)","a":"5-data-model-postgresql-schemas","t":"Schema Key tables market instruments, instrument broker ids, bars 1m (hypertable, source csv/dhan), bars 1m live, bars 1d, continuous aggregates bars 5m…bars 1h, context daily, calendar, corporate actions, (later) ticks, depth catalog tracked instruments, baskets, basket members (valid from/to), index membership data import profiles, import jobs, import issues portfolio transactions, lots, lot closures, positions, buckets, cash flows, valuations daily, corporate action adjustments research sim runs, sim trades (with MAE/MFE, R, exit reason, feature snapshot), cell stats, exit choices, regimes, training sets, model versions, hypotheses, learning changelog, lessons, experiments, execution gap (per trade: plan vs fill), autonomy settings, smart rules, meta models, entry windows, loss tags, digests trading accounts, account roles, account snapshots, plans, plan items (primary/reserve/rejected), outcomes, journal entries, fills, (later) orders, order events lab strategies, strategy versions, lab runs, lab results, test ledger config config versions (YAML, hash, author, activated at), active config ops commands, service schedules, service runs, validation runs, validation results, data quality issues, audit log, notifications insights alerts, action items (status: open / snoozed / done), action thresholds workflow approvals, suggestions auth ASP.NET Core Identity tables (owner user, password hash, lockout) ai conversations, tool calls (audit) hangfire job storage Every decision-relevant row carries as of timestamps and the config version / model version used."},{"d":2,"h":"6. API surface (REST + SignalR)","a":"6-api-surface-rest-signalr","t":"Area Endpoints (examples) Instruments & baskets GET /api/instruments?q=&type=&sector= · POST /api/tracked · DELETE /api/tracked/{id} · GET/POST/PUT /api/baskets · POST /api/baskets/{id}/members · GET /api/baskets/{id}/preview (rule) Data import POST /api/imports (upload) · POST /api/imports/{id}/preview · POST /api/imports/{id}/commit · POST /api/imports/{id}/undo · GET/PUT /api/import-profiles Portfolio GET /api/portfolio?groupBy=&asOf= (groupBy: bucket, basket, account, strategy, sector) · GET /api/portfolio/positions/{id} · POST /api/portfolio/transactions (manual/CSV) · GET /api/portfolio/history?from=&to= Live GET /api/live/active-set · PUT /api/live/pins Plans GET /api/plans?date=&account= · GET /api/plans/{id} · POST /api/plans/{id}/preopen-check Journal GET /api/journal?from=&to= · PATCH /api/journal/{id} (taken/skipped/notes) Reports GET /api/reports/{type}?lens=&from=&to=&basket=&strategy=&tf=&side=&exit=&regime=&account= · GET /api/reports/{type}/export?format= Learning GET /api/cells · GET /api/cells/{key} · GET /api/changelog · POST /api/changelog/{id}/revert · GET/POST /api/hypotheses · GET /api/learning/journey · GET /api/lessons · GET /api/execution-gap · POST /api/experiments (replay job, SignalR progress) · POST /api/experiments/{id}/shadow · POST /api/experiments/{id}/apply · GET/PUT /api/autonomy · GET/PUT /api/smart-rules · GET /api/smart-rules/evidence · GET /api/digest/latest · GET /api/loss-tags Strategy Lab POST /api/lab/strategies · POST /api/lab/validate · POST /api/lab/runs · GET /api/lab/runs/{id} · POST /api/lab/runs/{id}/promote Config GET /api/config · POST /api/config/drafts · POST /api/config/drafts/{id}/validate · POST /api/config/drafts/{id}/activate Auth POST /api/auth/login · POST /api/auth/logout · POST /api/auth/reauth Accounts GET/POST/PUT /api/accounts · PUT /api/accounts/{id}/roles (step-up) · POST /api/accounts/{id}/test · POST /api/accounts/{id}/sync Approvals GET /api/plans/{date}/review · POST /api/plans/items/{id}/{approve, modify, reject} · POST /api/plans/{date}/approve-all Suggestions GET /api/suggestions?status= · POST /api/suggestions/{id}/accept · POST /api/suggestions/{id}/reject Services GET /api/services · PUT /api/services/{id}/schedule (validated against dependency rules) · POST /api/services/{id}/run · POST /api/services/{id}/pause · GET /api/services/{id}/runs Data quality GET /api/quality?status= · GET /api/quality/{symbol} (checks, stored vs recomputed) · POST /api/quality/run · POST /api/quality/{symbol}/repair Insights GET /api/portfolio/actions?account=&severity= · POST /api/portfolio/actions/{key}/{snooze, done} · GET/POST/DELETE /api/alerts · GET /api/reports/insights Risk profiles GET/POST/PUT/DELETE /api/risk-profiles (step-up) Data GET /api/data/quality · GET /api/data/coverage Assistant POST /api/assistant/chat (streaming) Real-time SignalR /hubs/events: live prices & P&L (active set), alerts, job/import progress, nightly status"},{"d":2,"h":"7. Key flows","a":"7-key-flows","t":""},{"d":2,"h":"Daily timeline (trading day)","a":"daily-timeline-trading-day","t":"Time (IST) What runs 09:00–15:35 xd-feed: live data for the active set; quote polling for holdings; live P&L & alerts 09:10 Pre-open check arms approved tickets (after the 09:05 review cutoff) 15:50 EOD fetch: today's 1-minute + daily for all tracked instruments, gap backfill, aggregates refresh 16:30 Account sync: holdings, positions, trade history, ledger → portfolio & auto-journal; daily valuation 18:30 Nightly pipeline (below) → next-day plan"},{"d":2,"h":"Nightly pipeline (Hangfire recurring job, 18:30 IST)","a":"nightly-pipeline-hangfire-recurring-job-1830-ist","t":"Weekly: retrain/recalibrate (ML.NET job), exit re-selection, hypothesis loop. Monthly: full walk-forward review."},{"d":2,"h":"CSV import","a":"csv-import","t":"Upload or drop files → profile detection & preview in React → commit → Hangfire job parses (streaming), validates, maps symbols, bulk-COPYs into bars 1m, refreshes aggregates for the affected range → import report via SignalR → instruments auto-tracked. Details: 05-data-and-brokers.md §3."},{"d":2,"h":"Live active set","a":"live-active-set","t":"Planning (armed tickets) + Portfolio (open positions, holdings) + context indices + pins → xd-feed diffs the set and (un)subscribes on the Dhan WebSocket → ticks → live 1-minute bars + LTP → Portfolio/alerts → SignalR to React."},{"d":2,"h":"Strategy Lab run","a":"strategy-lab-run","t":"React editor → POST /api/lab/runs → Hangfire job in xd-worker (plugins in xd-sandbox) → progress over SignalR → results in lab schema → report page. Details: 11-strategy-lab.md."},{"d":2,"h":"8. Security","a":"8-security","t":"- Login required everywhere : single owner, ASP.NET Core Identity (password), idle timeout, lockout, password re-entry for sensitive actions for sensitive actions; HTTPS via Caddy on LAN; optional WireGuard for remote access (doc 04 §2). - Service identity : background services act on persisted desired state, not on user sessions; every action records the configuring actor for audit. - Secrets per container via Podman secrets; only xd-worker/xd-feed (data/account tokens) and later xd-exec (order tokens) receive broker secrets. - xd-mcp and the LLM use a read-only database role ; no tool can change config, plans or orders. - xd-sandbox has no network and a read-only data mount. - Audit log for config activations, promotions, approvals and (later) orders."},{"d":3,"h":"04 — Accounts, Access & Operating Model","a":"","t":"Four rules shape how xDrishti is used day to day: 1. Personal use only — one owner, only the owner's broker accounts. 2. Login required — nobody else can open or use the application. 3. Configure once, services run it — what you set up is executed by background services on the machine, not by your browser session. 4. Human in the loop — the system and the AI propose ; you confirm the decisions that matter."},{"d":3,"h":"1. Broker accounts and their roles","a":"1-broker-accounts-and-their-roles","t":"You can register any number of broker accounts. Each account is given one or more roles : Role What the account is used for Requirements Data Market data: instrument master, historical & end-of-day 1-minute data, live feed for the active set, quotes Dhan Data API subscription on this account Trading Receives next-day plan tickets (sized to its capital and risk profile); auto-journal of fills; later order execution Risk profile, capital source, allowed styles/instruments Portfolio Holdings, positions, trade history and ledger are synced and monitored Sync schedule, default bucket One account can hold several roles at once, for example: Account Data Trading Portfolio Notes : : : : : : Dhan · Main ✅ primary ✅ ✅ Pays the ₹499 Data API; trades and is monitored Dhan · Long-term — — ✅ Monitoring only (holdings, XIRR) Dhan · Swing ✅ standby ✅ ✅ Can take over data if the main account's token fails Upstox · Old (later) — — ✅ Monitoring only once the Upstox adapter exists Rules enforced by the system - Exactly one primary Data account ; optionally one standby that takes over automatically if the primary's token or subscription fails (only if it also has an active Data API subscription). - A Trading account must have a risk profile; plan allocation only goes to accounts with the Trading role. - Portfolio views include only accounts with the Portfolio role (filterable per account). - Removing a role stops the related services for that account; history is kept. - Every role change is audited and needs re-authentication (password). Per-account settings: display name, broker, client id, credential reference (secrets live in the macOS Keychain → Podman secrets, never in the database), roles, mode (paper / manual live; automated modes in a later phase), risk profile, capital source, sync schedule, token status & last successful sync."},{"d":3,"h":"1.1 Accounts screen","a":"11-accounts-screen","t":"View Content Accounts (list + detail) Left: every account with roles, token health, holdings value. Right: tabs Overview (value, P&L, funds, token, sync) · Roles · Trading (mode, risk profile, capital source/amount, styles, allowed instruments per style, per-account overrides of risk %, max entries, max open, daily loss) · Portfolio (default bucket, trade-history import start, include in totals, buckets) · Data (primary/standby, subscription & renewal, live-feed budget, failover test) · Connection (name, client id, Keychain reference, colour, notes, token refresh, test) · Activity (audit for this account) Role matrix All accounts × roles in one table; tick to change (step-up), pick the primary Data account Risk profiles Shared profiles (e.g. Standard, Conservative, Aggressive): risk per trade, max new entries/day, max open positions, daily loss, max per sector, max heat; shows which accounts use each Add account wizard Broker & identity → credentials (Keychain item, connection test) → roles → role settings → review & confirm with your password Automatic failover: if the primary Data account's token or subscription fails, the services switch to the standby Data account, notify you and record it in the audit log."},{"d":3,"h":"2. Access control (login)","a":"2-access-control-login","t":"Control Design Login Username + password on a centred sign-in panel; a locked session shows Welcome back · Unlock (password only, survives reload); single owner account created at first start. No second factor: the app is personal and reachable only on this machine / home LAN (a passkey can be added later if remote access is ever enabled) Password storage ASP.NET Core Identity hashing (PBKDF2); never stored in plain text Sessions Secure HTTP-only cookie; idle timeout 30 min (configurable); absolute timeout 12 h; \"lock\" button Lockout 5 failed attempts → 15-minute lockout; all attempts in the audit log Step-up auth Password re-entry for sensitive actions: account roles/credentials, config activation, enabling execution, deleting data Recovery One-time recovery codes generated at setup Every endpoint protected REST, SignalR, Hangfire dashboard and file downloads require login; only /health is anonymous Network Reachable only on the home LAN via HTTPS (Caddy); optional WireGuard for remote; MCP/LLM on the internal network only"},{"d":3,"h":"3. Operating model — configure once, services run it","a":"3-operating-model-configure-once-services-run-it","t":"The UI is a control plane : it records what you want. Background services are the execution plane : they do the work on the machine, whether or not you are logged in or the browser is open. - Every action you take is stored as desired state (e.g. \"INFY is tracked\", \"basket MyChoice contains …\", \"ticket T-123 approved\") plus an audit record (who, when, what changed). - Services run under a service identity , not your session. Logging out, closing the browser or the phone has no effect on scheduled work. - Services reconcile desired vs actual state: on every run and on start-up. If the Mac was asleep at 15:50, the end-of-day fetch runs as soon as the services are back (catch-up for missed schedules). - Jobs are idempotent, retried with back-off and resumable; failures raise in-app notifications. You do this (once) Services then do this (automatically) Track an instrument Backfill history (CSV, then Dhan), add to end-of-day fetch, build all timeframes Create a basket / add instruments Include in the next scan scope, reports and portfolio grouping Assign the Data role to an account Switch market-data jobs and the live feed to that account Assign the Portfolio role Nightly sync of holdings, trades, ledger; valuations; XIRR Assign the Trading role Allocate and size plan tickets for that account Approve tomorrow's tickets Pre-open check, arm tickets, subscribe live feed, trigger/stop/target alerts Drop CSV files in the inbox Import, validate, aggregate, report Activate a config version Apply from the next scheduled run Accept an AI suggestion Apply the change (e.g. add instrument to basket) and log it Services overview (default schedules — all editable on the Services screen): Service / job Default schedule Runs as Live feed (active set) Window 09:00–15:35, trading days xd-feed Holdings quote refresh Every 5 min, 09:15–15:30 xd-feed Pre-open check & arming 09:10 (after the 09:05 review cutoff and NSE pre-open price discovery, before the 09:15 open) xd-worker Price alerts & action center Every 1 min, 09:15–15:30 xd-worker End-of-day fetch & aggregation 15:50 xd-worker Data validation Runs after the EOD fetch xd-worker Account & portfolio sync 16:30 xd-worker Nightly pipeline → proposed plan 18:30 xd-worker AI suggestions & briefing After the nightly pipeline; starts xd-llm on demand and waits for readiness (a 30B load took 22–105 s) xd-worker + xd-llm CSV inbox watcher Continuous xd-worker Weekly retrain / monthly review Sat 10:00 / 1st of month xd-worker Backup Daily 23:30 xd-backup"},{"d":3,"h":"3.1 Schedule configuration","a":"31-schedule-configuration","t":"Each service has an editable schedule stored in the database (not in code): Setting Options Schedule type Daily at a time (chosen days) · Weekly · Run after another service · Time window · Every N minutes within a window · Continuous Execution Enabled/paused · retries (0–5) · timeout · catch up missed runs · notify on failure Parameters Service-specific, e.g. EOD throttle and gap look-back; validation sessions, tolerance and spike multiple; pre-open gap threshold; live-feed instrument cap Dependency & timing rules (checked on every change; errors block saving, warnings are shown): pre-open check after the review cutoff and before 09:15 (warning before 09:08); EOD fetch after 15:35; nightly pipeline after the EOD fetch and the portfolio sync; live window covers 09:15–15:30; no backup during market hours; no circular \"run after\" chains; window start before end. The Services screen also shows a trading-day timeline with market hours, the review cutoff, every scheduled run and the run-after chains, plus a preview of the next three runs while editing."},{"d":3,"h":"4. Human in the loop","a":"4-human-in-the-loop","t":""},{"d":3,"h":"4.1 Who decides what","a":"41-who-decides-what","t":"Category Examples Decision Automatic (no approval) Data fetch, aggregation, quality checks, grading, cell statistics, portfolio sync, valuations Services Proposed → you confirm Next-day trade tickets · AI instrument suggestions (track, add to / remove from basket) · hypothesis promotions · cell promotions to Active · config change proposals · (later) semi-auto orders You Only you Accounts & roles, credentials, baskets you create, risk limits, enabling execution You"},{"d":3,"h":"4.2 Next-day plan approval","a":"42-next-day-plan-approval","t":"- The nightly pipeline produces a proposed plan (primary tickets + reserve list) with reasons, P(win), expected R and the AI briefing. You review it in the evening or morning (phone works via the PWA). - Actions per ticket: Approve , Modify (reduce size, tighten stop, change account, choose reserve instead), Reject . Bulk \"approve all within limits\" is available. Every modification is re-validated against risk limits. - Review cutoff (default 09:05): unreviewed tickets lapse (safe default — unreviewed policy: lapse). - Only Approved → Armed tickets enter the live active set and alerts. - Every decision is recorded. Reports compare system proposal vs your decision — e.g. \"rejected tickets would have made +4.2R this month\" — so you can see whether your overrides add value."},{"d":3,"h":"4.3 AI suggestions inbox","a":"43-ai-suggestions-inbox","t":"The assistant and learning engine post suggestions to an inbox ; each has a reason, evidence and an expiry: Suggestion Example If accepted Track instrument \"Track PERSISTENT — strong RS, 3 passing setups in Best stocks rules\" Instrument tracked & backfilled Add to / remove from basket \"Add TATAPOWER to Best stocks (rule match, liquidity ok)\" Membership updated (dated) Next-day focus \"Prefer swing over intraday tomorrow: high-VIX regime\" Shown with the plan (no automatic effect) Hypothesis / promotion \"ORB 15m BUY: target 2.0R → 2.5R passed walk-forward + shadow\" Config version created for activation Rejected suggestions are not repeated for a configurable number of days."},{"d":3,"h":"5. Data model additions","a":"5-data-model-additions","t":"Table Purpose trading.accounts Broker accounts (no secrets) trading.account roles account id, role (data/trading/portfolio), is primary/standby, enabled, settings auth. ASP.NET Core Identity tables (user, password hash, lockout) ops.commands Desired-state changes and requested actions, status, actor, timestamps ops.audit log Every login, configuration change, approval and service action workflow.approvals Item type, item id, decision, modifications, actor, decided at, cutoff workflow.suggestions Source (AI / engine), type, payload, reason, expiry, status ops.service runs Service/job runs with schedule, start/end, outcome, catch-up flag"},{"d":4,"h":"1. Data sources (v1)","a":"1-data-sources-v1","t":"Source Role Cost Your CSV files (1-minute) Historical bootstrap and any bulk history you provide ₹0 Dhan Data API The only market-data API in v1: instrument master, end-of-day 1-minute/daily fetch for tracked instruments, live feed for the active set, quotes for holdings ₹499 + taxes / 30 days, on one account Dhan Trading API Funds, positions, holdings, trade history, ledger — every Dhan account Free NSE files (optional) Free official bhavcopy / corporate actions / holidays for reconciliation ₹0 Upstox Adapter kept for later (second broker / fallback); disabled in v1 —"},{"d":4,"h":"2. Three data tiers","a":"2-three-data-tiers","t":"- Tier A fills history once (and whenever you add instruments or files). - Tier B keeps every tracked instrument complete each evening — the learning engine and nightly plan use only Tier A/B data. - Tier C streams live data only for what you are actively trading or holding , keeping the system light."},{"d":4,"h":"3. CSV import (1-minute data)","a":"3-csv-import-1-minute-data","t":""},{"d":4,"h":"3.1 How files arrive","a":"31-how-files-arrive","t":"- Upload in the Data → Import screen (multiple files / zip), or drop into the watched folder data/inbox/ (mounted into xd-worker), or CLI xd data import <path --profile <name . - One file per instrument (symbol from file name) or multi-instrument files (symbol column) — both supported."},{"d":4,"h":"3.2 Import profiles (column mapping)","a":"32-import-profiles-column-mapping","t":"Different CSV sources use different layouts; a saved profile describes yours once: csv profiles: my 1min files: delimiter: \",\" header: true symbol: { from: filename, pattern: \"^(?<symbol [A-Z0-9&-]+) 1min\\\\.csv$\" } or { from: column, name: symbol } exchange: NSE columns: { timestamp: datetime, open: open, high: high, low: low, close: close, volume: volume, oi: null } timestamp: { format: \"yyyy-MM-dd HH:mm:ss\", timezone: Asia/Kolkata, label: bar start } bar start bar end prices: { adjusted: false } raw prices; system applies corporate-action adjustments session filter: { from: \"09:15\", to: \"15:29\" } Example accepted file (TATASTEEL 1min.csv): datetime,open,high,low,close,volume 2026-10-05 09:15:00,152.10,152.60,151.95,152.40,412530 2026-10-05 09:16:00,152.40,152.55,152.20,152.30,198220"},{"d":4,"h":"3.3 Import pipeline","a":"33-import-pipeline","t":"1. Detect profile (or use the one specified); preview the first rows in the UI before committing. 2. Map symbol → master list; unknown symbols are listed for you to map or skip (never guessed). 3. Validate each row: timestamp parse, within session, OHLC consistency (low ≤ open/close ≤ high), no negative volume, no duplicate timestamps; bar-end labels shifted to bar-start. 4. Upsert into market.bars 1m with source = csv. Precedence on overlap (configurable): Dhan official CSV live; conflicts beyond tolerance are logged, not silently overwritten. 5. Refresh aggregates for the affected instrument/date range. 6. Report : rows imported/updated/rejected per file, coverage before/after, quality issues — stored as an import job you can review and undo (by job id). Instruments in the files are auto-added to the tracked list (configurable), so they are kept up to date by Tier B afterwards."},{"d":4,"h":"4. Aggregation to other timeframes","a":"4-aggregation-to-other-timeframes","t":"All timeframes are built from 1-minute bars — identical logic for CSV and Dhan data. Rule Detail OHLCV open = first, high = max, low = min, close = last, volume = sum, OI = last Alignment Intraday buckets anchored to the 09:15 session open: 15m = 09:15, 09:30…; 1h = 09:15–10:15 … 14:15–15:15, then 15:15–15:30 (partial, flagged) Timeframes 5m, 10m, 15m, 30m, 1h (and any custom minute size) · 1D · 1W · 1M Daily bar daily source: official (Dhan daily candles, default when available) or derived (from 1-minute) — official open uses the pre-open auction price, so the two can differ slightly Missing minutes Bucket built from available minutes; completeness % stored; buckets below threshold flagged Special sessions Holidays skipped; special sessions (e.g. Muhurat) from the calendar Implementation TimescaleDB continuous aggregates (time bucket with 09:15 origin) for intraday; 1D/1W/1M from daily table; refreshed after imports and after the EOD fetch; real-time aggregation combines materialised + newest rows"},{"d":4,"h":"5. Real-time data — the active set only","a":"5-real-time-data-the-active-set-only","t":"To keep the system fast and within limits, live data is streamed only for the active set : Member of active set Why Method Open intraday / swing positions (all accounts) Live P&L, stop/target alerts WebSocket (quote mode) Today's armed plan tickets (until triggered/expired) Trigger detection & alerts WebSocket Context indices (NIFTY 50, NIFTY BANK, INDIA VIX) Market filter, live context WebSocket Pinned basket (optional) Your live watch list WebSocket (counts toward budget) Long-term holdings Valuation Quote API polling (≤ 1,000 per request, every 5 min) - Dhan limits: up to 5 WebSocket connections × 5,000 instruments; our active set is typically < 100 → one connection. live.max ws instruments caps it (default 200). - xd-feed builds live 1-minute bars in memory from ticks and persists them to market.bars 1m live. - At end of day, Tier B fetches the official 1-minute bars; live bars are reconciled and discarded. - Subscriptions update automatically when a ticket arms, a position opens/closes, or holdings change. - Runs 09:00–15:35 on trading days; auto-reconnect; gaps logged."},{"d":4,"h":"6. End-of-day fetch (Tier B)","a":"6-end-of-day-fetch-tier-b","t":"Scheduled after close (default 15:50 IST) before the nightly pipeline: 1. Refresh Dhan token; refresh instrument master (new listings, lot sizes, expiries). 2. For every tracked instrument: fetch today's 1-minute candles and daily candle (throttled, chunked, resumable). 3. Detect gaps for recent days and backfill; corporate actions; calendar. 4. Quality checks (§9); reconcile with NSE files if enabled. 5. Refresh aggregates; then the nightly pipeline starts (doc 03 §7). Adding new tracked instruments triggers a backfill job (CSV first, then Dhan for gaps)."},{"d":4,"h":"7. Broker abstraction","a":"7-broker-abstraction","t":"Interface Methods v1 adapter IMarketDataProvider instruments, intraday/daily history, quotes Dhan ILiveFeed subscribe/unsubscribe, tick stream Dhan WebSocket IAccountReader funds, positions, holdings, trades (history), ledger Dhan ITokenProvider get, refresh, expiry Dhan (API key & secret flow, 24 h tokens) IOrderExecutor place/modify/cancel (later phase) — IFileImporter CSV profiles → bars CSV Adding Upstox or another broker later = one adapter project + config. The instrument master maps each broker id (Dhan security id + segment) to a canonical symbol; mapping mismatches are quality issues, never guessed."},{"d":4,"h":"8. Accounts","a":"8-accounts","t":"Any number of accounts (all your own), each with roles — Data, Trading, Portfolio — as described in doc 04 §1. The market-data jobs and live feed in this document always use the primary Data account (with automatic failover to a standby Data account if configured). Trading accounts have mode (paper / manual live; automated modes later), risk profile, allowed styles/instruments and capital source. Nightly sync reads funds, positions, holdings, trade history and ledger → feeds the auto-journal (fills matched to plan tickets) and portfolio monitoring (doc 12)."},{"d":4,"h":"9. Storage","a":"9-storage","t":"Table Type Notes market.bars 1m Hypertable, compressed after 7 days (instrument id, ts), source = csv / dhan eod market.bars 1m live Hypertable, short retention Live bars for the active set market.bars 5m … bars 1h Continuous aggregates 09:15-anchored market.bars 1d Table Official or derived (flagged) market.bars 1w, bars 1m month Views/aggregates From daily market.context daily Table Indices, VIX, breadth, regime data.import profiles, data.import jobs, data.import issues Tables CSV import config, history, rejected rows Adjustment factors Table Research reads adjusted views; plans use raw prices Size: 200 instruments × 8 years of 1-minute data ≈ 150 M rows → 5–10 GB compressed."},{"d":4,"h":"10. Data quality","a":"10-data-quality","t":"Check Action Missing minutes (no halt) Backfill from Dhan; flag if unresolved Spike X × ATR with reversal Flag bad tick OHLC inconsistency / duplicate timestamps (CSV) Reject row, report Timestamp label mismatch (bar end vs start) Detected by session boundary check; profile fix suggested CSV vs Dhan conflict beyond tolerance Keep by precedence; log Unapplied corporate action Alert Rename / merger / delisting Master update; history linked Circuit-locked days Mark unfillable The nightly plan is not produced (fail closed) if index data fails or more than X% of tracked instruments fail; individual instruments that fail validation are skipped by the scan (per-instrument fail-closed)."},{"d":4,"h":"10b. Data quality window (validation workbench)","a":"10b-data-quality-window-validation-workbench","t":"The Data validation service runs after every end-of-day fetch (and on demand) over the last N sessions (default 5) of every tracked instrument: Check How Completeness 375 one-minute bars per session; lists missing minutes Bar sanity low ≤ open/close ≤ high, positive prices Duplicates No repeated timestamps Spikes Move k × median one-minute move and 1% Aggregates vs 1-minute Every stored 5m/15m/30m/1h/1D bucket is recomputed from the 1-minute bars with an independent reference implementation and compared exactly (OHLC and volume) — catches aggregates not refreshed after late data Derived vs official daily 1D built from 1-minute vs the broker's official daily candle (±0.05% OHLC, ±1% volume) Freshness Data present up to the last trading day The Data quality screen lists every tracked instrument with status (pass / warning / fail), coverage, bars checked, missing minutes, per-timeframe aggregate status, official-daily status and source (CSV / Dhan), plus a data quality score. Inspect shows each check, a side-by-side table of stored vs recomputed buckets (with \"differences only\"), the chart built from 1-minute data and the missing minutes. Re-fetch / Refresh aggregates repair an instrument and re-validate it automatically; every run is kept in a history."},{"d":4,"h":"11. Biases avoided","a":"11-biases-avoided","t":"Survivorship (historical index membership incl. delisted stocks), look-ahead (closed bars only; higher-TF from last closed bar; point-in-time regime), selection (basket rules are dated; point-in-time membership available)."},{"d":5,"h":"06 — Instruments & Baskets","a":"","t":"How you choose what the system works on and how you group and evaluate it."},{"d":5,"h":"1. Concepts","a":"1-concepts","t":"Concept Meaning Master list Every instrument in Dhan's instrument (scrip) master — equities, indices, futures, options — refreshed nightly, mapped to canonical symbols (doc 05) Tracked instrument An instrument you've switched on. Only tracked instruments get historical data, end-of-day updates, scans and analytics Basket A named group of tracked instruments; an instrument can be in many baskets Scope Which basket(s) a strategy scan, a Strategy Lab test, a report or a portfolio view applies to"},{"d":5,"h":"2. Master list & tracked instruments","a":"2-master-list-tracked-instruments","t":"- Search & add from the Instruments screen: filter the master list by name, symbol, exchange, segment, instrument type, sector, index membership, F&O eligibility, price, turnover. - Bulk add by pasting symbols, uploading a CSV list, or adding all members of an index/rule-based basket. - On activation the system backfills history: first from your CSV files if present, then gaps from the Dhan historical API (1-minute up to 5 years, daily since listing), and builds all timeframes. - On deactivation collection stops; history is kept (re-activation only fills the gap). - Status shown per instrument: data coverage (from/to), last update, quality issues, baskets, open positions. Field Example Canonical symbol NSE:TATASTEEL Broker ids Dhan security id + segment Type / segment EQ / NSE EQ (also IDX, FUT, OPT) Sector / industry Metals Lot size, tick size 1 / 0.05 (futures: contract lot size) Flags F&O eligible, ASM/GSM, in ban period Tracking active since 2026-10-15; data from 2021-10-01"},{"d":5,"h":"3. Baskets","a":"3-baskets","t":""},{"d":5,"h":"3.1 Basket types","a":"31-basket-types","t":"Type How membership is defined Examples Manual You add/remove instruments MyChoice, MyLongTerm, Best stocks, Watchlist Rule-based (dynamic) A saved filter re-evaluated nightly \"F&O stocks with turnover ₹50 Cr\", \"Nifty 50 members\", \"Sector = IT\", \"Near 52-week high\" System Maintained automatically Open positions, Holdings, Today's plan, Paused-cell instruments"},{"d":5,"h":"3.2 Basket attributes","a":"32-basket-attributes","t":"Attribute Purpose Name, colour, description Display Purpose trading · long term · watch — drives defaults (e.g. long-term baskets excluded from intraday scans) Allowed styles / sides e.g. MyLongTerm: swing BUY only Strategies in scope Which strategies scan this basket (default: all enabled) Risk profile override (optional) e.g. smaller risk per trade for a speculative basket Target weights (optional, long-term) For allocation drift view in the portfolio Membership history Added / removed dates and notes — enables point-in-time evaluation"},{"d":5,"h":"3.3 How baskets are used","a":"33-how-baskets-are-used","t":"Use Example Scan scope Nightly plan scans \"Best stocks\" and \"MyChoice\" for intraday; \"MyLongTerm\" only for swing BUY Strategy Lab universe \"Test VWAP RSI TREND on MyChoice, 2022–today\" Reports lens Compare results of all baskets side by side Portfolio grouping Value, return and XIRR per basket (doc 12) Live watch Pin a basket to the live price panel (counts toward the live-feed budget, doc 05 §5)"},{"d":5,"h":"4. Evaluation lenses — looking at results from different angles","a":"4-evaluation-lenses-looking-at-results-from-different-angles","t":"Every analytic screen uses the same lens + filters model: pick the lens (how rows are grouped), then filter by date range, source, account, style, strategy, timeframe, side, exit, regime, basket. Lens Rows Typical question All trades One summary + equity curve \"How is the whole system doing this quarter?\" By basket One row per basket \"Is MyChoice better than Best stocks for intraday?\" By instrument One row per symbol \"Which stocks consistently work / fail?\" By individual trade One row per trade, drill to replay \"Why did this TATASTEEL trade lose?\" By strategy / cell Strategy × TF × side × exit \"Which setups work in which basket?\" By account One row per broker account \"How does each account perform?\" By sector / regime / month Grouped rows \"Where and when does it work?\" Lenses can be combined as a pivot (e.g. basket × strategy heatmap of expectancy, or basket × month returns). Each basket row also shows a buy-and-hold benchmark (equal-weight basket return and Nifty 50 over the same period) so trading results are judged against simply holding the basket. Overlapping baskets: an instrument in several baskets appears under each, so per-basket totals are not additive — the UI says so. For additive totals (e.g. portfolio value) a position has one portfolio bucket (doc 12 §5). Point-in-time vs current membership: reports default to current membership; switch to as-of membership to evaluate a basket exactly as it was composed on each trade date."},{"d":5,"h":"5. Data model","a":"5-data-model","t":"Table Key columns market.instruments id, canonical symbol, type, segment, sector, lot size, tick size, flags, listed on market.instrument broker ids instrument id, broker, broker id, segment catalog.tracked instruments instrument id, active, active since, data from, data to, last update catalog.baskets id, name, type (manual/rule/system), purpose, colour, settings (JSON), rule (JSON) catalog.basket members basket id, instrument id, valid from, valid to, note, target weight"},{"d":5,"h":"6. Screens","a":"6-screens","t":"- Instruments — master-list search with facets; tracked list with coverage/quality/basket chips; bulk actions (track, untrack, add to basket, backfill). - Baskets — list with key stats; editor (manual add/remove, drag & drop, rule builder with live preview); basket detail (members, performance by lens, benchmark, open positions)."},{"d":6,"h":"1. Strategy anatomy","a":"1-strategy-anatomy","t":"Part Description Example (Opening Range Breakout) id Unique name ORB styles intraday / swing intraday timeframes Allowed entry timeframes 5m, 15m, 30m sides BUY / SELL both setup Conditions known before the trigger (evaluated tonight) High relative volume yesterday, NR7, trend filter trigger What must happen to enter (evaluated tomorrow) Candle closes above OR-high (BUY) valid window When the trigger may fire 09:30–11:30 initial stop Where the idea is wrong OR opposite side / trigger-candle extreme / k × ATR filters Context gates Higher-TF trend agrees; not results day invalidation Cancel if… Gap beyond trigger; stop level hit before trigger params ≤ 4 tunable values OR length, ATR multiple Built-in strategies are written in the same rules language users use in the Strategy Lab (doc 11), so there is one way to define a strategy."},{"d":6,"h":"2. Conditional trade plans","a":"2-conditional-trade-plans","t":"Intraday entries can't be fixed the night before, so each plan item is a conditional ticket — and the simulator tests exactly this ticket on history: BUY RELIANCE INTRADAY 15m ORB basket: Best stocks account: dhan main Trigger : 15m candle CLOSE above 2,948.0 between 09:30 and 11:30 Entry : at trigger-candle close (limit +0.1% max) Stop : 2,921.5 (OR low) → risk/share 26.5 Exit : 50% at 1R, stop → breakeven, trail rest ATR(15m)×2; square-off 15:15 Size : 37 shares (risk ₹980 = 0.49% of capital) P(win) : 0.57 (n=214, regime UP LOW VOL) E[R]: +0.38 after costs Cancel : open 2,960 (gap 0.5 ATR) or 2,921.5 touched before trigger Why : NR7 yesterday, rel-volume 1.8×, 1h & 1D uptrend, sector strongest Swing tickets from daily bars: signal known at close; trigger typically \"buy-stop above today's high tomorrow\" or \"enter at open if gap within limits\"."},{"d":6,"h":"3. Starter library","a":"3-starter-library","t":"Each mirrored for SELL where sensible. Most cells will fail qualification — expected and healthy. Intraday (5m–1h): ORB (opening-range breakout) · PDH PDL BREAK / PDH PDL REJECT (previous-day high/low) · VWAP PULLBACK · VWAP RECLAIM · EMA PULLBACK (9/21 EMA with higher-TF trend) · GAP GO / GAP FILL · INSIDE BAR BO · CPR (central pivot range) · MEAN REV BANDS. Swing (1h/1D, ≤ 5 sessions): BASE BREAKOUT · TREND PULLBACK (20 EMA / 50 DMA) · NR7 ID BO · RSI2 REVERSION (above/below 200 DMA) · BB SQUEEZE · HIGH 52W MOMENTUM · FAILED BREAKOUT · RS ROTATION (strongest stocks in strongest sectors)."},{"d":6,"h":"4. Multi-timeframe mapping","a":"4-multi-timeframe-mapping","t":"Entry TF Bias TFs Typical style 5m 15m, 1h Intraday 10m 30m, 1h Intraday 15m 1h, 1D Intraday 30m 1h, 1D Intraday / short swing 1h 1D Intraday / swing 1D 1W Swing Confluence (same symbol & side on several timeframes/strategies) is a feature and a selection bonus."},{"d":6,"h":"5. Feature catalogue (point-in-time)","a":"5-feature-catalogue-point-in-time","t":"Group Examples Trend EMA slopes (9/21/50/200), price vs EMAs, ADX, swing structure, supertrend Momentum RSI(2/14), ROC, MACD histogram, distance from N-day high/low Volatility ATR %, ATR percentile, Bollinger bandwidth, NR4/NR7, inside bars, gap in ATR Volume Relative volume (same time-of-day), delivery %, OI change Levels Distance to previous-day H/L/C, CPR width, VWAP distance, 52-week high/low, round numbers Relative strength Stock vs index, stock vs sector, sector vs index (5/20/60 days) Market context Index trend/ADX, VIX level/percentile/change, breadth Calendar Weekday, time of day, expiry day/week, pre/post holiday, days to results Plan geometry Stop distance in ATR, room to next obstacle in R, achievable R:R"},{"d":6,"h":"6. Market regime","a":"6-market-regime","t":"Daily label from index data: trend (UP / DOWN / RANGE via DMA slope + ADX) × volatility (LOW / NORMAL / HIGH via VIX and ATR percentiles) → up to 9 regimes. Used to condition statistics and as a feature."},{"d":6,"h":"7. Side specifics","a":"7-side-specifics","t":"- BUY and SELL are learned separately (different speed, stops, regimes). - Intraday SELL: cash (MIS) or futures; swing SELL: futures only. - Circuit-locked stocks excluded on the locked side."},{"d":7,"h":"1. R-multiples","a":"1-r-multiples","t":"- 1R = amount risked = entry − initial stop × qty. All results are in R, so trades are comparable. - Expectancy E[R] = P(win)·avg win R − P(loss)·avg loss R − cost R. - Break-even win rate before costs: 33.3% at 1:2, 25% at 1:3."},{"d":7,"h":"2. Exit policy library","a":"2-exit-policy-library","t":"Policy Description Key parameters FIXED RR Full exit at k×R or stop k ∈ {1.5, 2, 2.5, 3} PARTIAL BE Book x% at T1, stop → breakeven, rest at T2 x, T1, T2 PARTIAL TRAIL Book x% at T1, trail remainder x, T1, trail ATR TRAIL Chandelier/ATR trail after activation period, multiple, activate at STRUCTURE TRAIL Trail beyond prior swing / previous candle lookback EMA TRAIL Exit on close beyond EMA length PYRAMID Add at progress levels, trail combined position see §4 TIME STOP Exit if not ≥ +x R after N bars/sessions x, N SESSION EXIT Intraday square-off time MAX HOLD Swing exit at end of session N N ≤ 5 EVENT EXIT Exit before results days before SESSION EXIT (intraday) and MAX HOLD (swing) are always on."},{"d":7,"h":"3. How the exit is chosen","a":"3-how-the-exit-is-chosen","t":"Per cell (weekly): replay the same historical entries under every candidate policy; choose by out-of-sample risk-adjusted expectancy (mean R − λ·downside dev R), requiring minimum samples and stability across folds — prefer the middle of a plateau over a sharp peak. From MAE/MFE (trade \"nature\"): - Stop: if 90% of winners never went beyond 0.8R adverse, 1R is sound; if winners routinely dip 1.2R, the stop is too tight. - Target: if median MFE is 2.4R but only 30% reach 3R, prefer 2–2.5R or partial booking. - Trail activation: where MFE giveback becomes common. Per trade (tonight): scale by current ATR; snap to structure (swing points, previous-day levels, round numbers); obstacle check — cap target before a strong level or skip if achievable R:R < min rr; reduce target for late intraday triggers (learned)."},{"d":7,"h":"4. Pyramiding","a":"4-pyramiding","t":"Used only where the cell shows trend persistence (fat MFE tail), mostly 30m+ and swing. Parameter Default Initial position 50% of full size Add triggers +1R, +2R (on trigger-TF close) Add sizes 30%, 20% Max adds 2 Risk rule Before each add, move stops so total open risk ≤ initial 1R"},{"d":7,"h":"5. Time rules","a":"5-time-rules","t":"Rule Intraday Swing Latest entry e.g. 14:30 Signal valid N sessions (default 1) Forced exit Square-off (e.g. 15:15) Close of session ≤ 5 Time stop e.g. < +0.5R after 6 bars e.g. < +0.5R after 2 sessions Overnight gap — Gap through stop ⇒ filled at open (simulated realistically)"},{"d":7,"h":"6. Position sizing (per account)","a":"6-position-sizing-per-account","t":"risk amount = account capital × risk per trade pct qty = min(risk amount / entry − stop , max capital per trade / entry, liquidity cap) qty = round down to lot(qty) futures skip if qty < 1 lot, or cost R max cost R Optional confidence scaling (capped fractional Kelly, 0.5×–1.25×) — off until calibration is proven in paper trading. Learned multipliers on top (doc 09 §14): meta-labelling size × 0.5–1.5, equity-curve throttle × 0.5 while the system's equity is below its 20-trade average, reduced market-gate day × 0.75. The multipliers never raise risk above the profile's maximum per trade."},{"d":7,"h":"7. Portfolio limits (per account, from its risk profile)","a":"7-portfolio-limits-per-account-from-its-risk-profile","t":"Limit Default Max new entries per day 3 Max open positions 5 Max total open risk (heat) 3% Max per sector 2 Max pair correlation (60-day returns) 0.60 — above it the lower-ranked ticket goes to reserve Daily loss limit −2R or −1.5% → no new entries Weekly loss limit −5R → half size next week Max drawdown (goal) 8% → halt new entries, review Consecutive losses in a cell 4 → pause cell"},{"d":7,"h":"8. Costs & slippage","a":"8-costs-slippage","t":"Brokerage, exchange charges, STT/CTT, GST, stamp duty, SEBI fees — from your broker's current charge sheet in config (rates change with budgets). Slippage: ticks + fraction of bar range; extra for stop exits and gaps. Every simulation includes costs."},{"d":8,"h":"09 — Learning Engine","a":"","t":"\"Self-learning\" = continuously re-measuring which setups, timeframes, sides and exits work in which market conditions, and shifting recommendations accordingly — with guards against fooling itself."},{"d":8,"h":"1. Four layers","a":"1-four-layers","t":"Layer 1 — Cell statistics. For each cell (strategy, tf, side, style, exit policy, regime) and windows (all / 250 days / 60 days): n, win rate, avg win/loss R, expectancy, profit factor, max drawdown, MAE/MFE quantiles. Win rate uses a Beta prior shrunk toward the parent group when n is small; confidence = lower bound of the credible interval; exponential recency weighting. Layer 2 — Exit selection. See doc 08 §3. Layer 3 — Meta-model (meta-labeling). - Labels: triple barrier — target, stop, time limit (session end / max hold). - Model: gradient-boosted trees (ML.NET LightGBM, FastTree fallback) per style × side (strategy as feature), isotonic (PAV) calibration , per-prediction feature contributions + permutation importance; trained and scored in-process in .NET. - Must beat baselines (logistic regression; cell stats only) out-of-sample, else not used. - Top contributing features stored with each recommendation. Layer 4 — Monitoring & adaptation. - Regime-conditioned statistics. - Drift : rolling expectancy below the backtest band for K checks ⇒ auto-pause; paused cells keep being shadow-graded and re-qualify automatically. - Champion/challenger for models and parameters. - Learning changelog for every automatic change, with evidence."},{"d":8,"h":"2. Validation: purged walk-forward","a":"2-validation-purged-walk-forward","t":"train (3y) -gap- -- test (3m) -- train -gap- -- test -- Only test windows count. Gap ≥ max holding (5 sessions). Tuning only inside train windows."},{"d":8,"h":"3. Daily feedback loop","a":"3-daily-feedback-loop","t":"1. Grade yesterday's primary, reserve and rejected items against actual data. 2. Attach real fills (auto-journal) → measure live vs paper slippage; grade on executed prices (§9). 3. Append outcomes with decision-time feature snapshots. 4. Update cell stats; run drift and lesson monitors (§10). 5. Weekly: retrain, recalibrate, challenger test."},{"d":8,"h":"4. Outputs per candidate","a":"4-outputs-per-candidate","t":"Output Meaning p win Calibrated probability of target before stop/time limit exp R / exp R lower Expected R after costs / conservative bound (used for ranking) exit policy Chosen policy with fitted levels expected hold Typical bars/sessions to resolution confidence Sample size, calibration, regime match reasons Top features + cell statistics in plain text"},{"d":8,"h":"5. Hypothesis loop (one variable at a time)","a":"5-hypothesis-loop-one-variable-at-a-time","t":"Hypotheses can come from the LLM, a parameter grid, or you. Live strategies are never edited directly by an LLM. Record example: {\"id\":\"H-2026-10-18-01\",\"cell\":\"ORB 15m BUY INTRADAY \",\"variable\":\"exits.FIXED RR.rr\",\"from\":2.0,\"to\":2.5, \"rationale\":\"Median MFE 2.7R over 120 OOS trades\",\"status\":\"shadow\", \"backtest\":{\"oos trades\":212,\"exp R champion\":0.21,\"exp R challenger\":0.26}}"},{"d":8,"h":"6. Overfitting guards","a":"6-overfitting-guards","t":"1. Out-of-sample only for decisions. 2. Minimum 30 OOS trades per cell. 3. ≤ 4 parameters per strategy; coarse grids; plateaus. 4. Multiple-testing adjustment (deflated Sharpe, stricter thresholds as tests grow). 5. Costs always on. 6. Monte Carlo trade reshuffling for drawdown expectations. 7. Paper stage before live. 8. Random-entry baseline with identical exits."},{"d":8,"h":"7. Cell lifecycle","a":"7-cell-lifecycle","t":"Default gates: OOS trades ≥ 30 · expectancy ≥ +0.15R · profit factor ≥ 1.2 · positive in ≥ 60% of folds · max drawdown ≤ 10R · calibration error ≤ 5 pp."},{"d":8,"h":"8. Compute (M4 Pro, 48 GB)","a":"8-compute-m4-pro-48-gb","t":"Full walk-forward ( 20 strategies × 6 TFs × 2 sides × 8 exits × 200 symbols × 5 years): a few hours in parallel .NET workers, monthly/weekends. Nightly incremental: minutes. Model training: minutes."},{"d":8,"h":"9. Execution feedback: learning from what actually happened","a":"9-execution-feedback-learning-from-what-actually-happened","t":"The system learns from your real fills , not only from chart prices. Every graded trade carries both the plan prices and the executed prices, and the difference is decomposed every week: Feedback What the system changes automatically Labels use real fills Outcomes, R-multiples and MAE/MFE are computed from executed prices — the model learns what is achievable Slippage per liquidity bucket Re-estimated weekly from your fills; used in every backtest, experiment and E[R] Missed triggers (touched, not filled) Trigger buffer and order type (market vs limit-with-buffer) per instrument Partial fills / broker rejections Lower the cell's capacity score ; selection prefers tickets that can actually be filled Your overrides Graded against the system's proposal (Reports → Decisions); feeds the autonomy recommendation (§13) A setup that is profitable on plan prices but not after execution is treated as not profitable ."},{"d":8,"h":"10. Lessons: problem → diagnosis → fix → result","a":"10-lessons-problem-diagnosis-fix-result","t":"When a monitor fires, the system opens a lesson — a record of what went wrong and what was done about it. Monitors: drawdown beyond the Monte Carlo band, drift (CUSUM on expectancy), calibration error, execution gap, decision drag, tail losses, data-quality failures. Category Typical diagnosis Typical fix Regime Setup fails in one volatility/trend regime Regime gate for that cell Exits MFE after stop is high (stops inside noise); targets rarely hit Stop/target multiple (one variable) Execution Fills worse than plan on illiquid names or at the open Liquidity filter, order type, entry window Calibration Predicted win rate above actual Recalibration (PAV), stronger shrinkage prior Decisions Your rejections or modifications cost R Auto-approval rule (autonomy) Drift Edge decays over months Pause / retire; promote a shadow challenger Events Gaps through stops around results Event filter, gap-aware sizing Data Bad bars caused false signals Repair, fail-closed gate {\"id\":\"L1\",\"category\":\"Regime\",\"detected\":\"2025-11-10\",\"cell\":\"ORB 15m INTRADAY \", \"problem\":\"Win rate 47% → 29% over 38 trades with INDIA VIX 18 (−9.4R)\", \"diagnosis\":\"64% of losers hit the stop within 15 minutes (false breakouts in volatile opens)\", \"fix\":{\"variable\":\"regime gate.vix max\",\"from\":null,\"to\":18,\"how\":\"auto\",\"evidence\":\"7/8 folds, +0.38R\"}, \"result\":{\"metric\":\"exp R\",\"before\":-0.21,\"after\":0.17,\"trades after\":60},\"status\":\"resolved\"} Lessons are kept forever and shown on the Learning screen with a before/after chart, the walk-forward evidence and two actions: Revert and Re-run with a different value (opens §12 pre-filled)."},{"d":8,"h":"11. Making learning visible (Learning screen)","a":"11-making-learning-visible-learning-screen","t":"View Question it answers Journey Is the system improving? Weekly live expectancy vs a frozen copy of last year's model (the counterfactual) vs plan prices; red bands from problem to fix; pins for lessons; cumulative R uplift; model versions Learning health One 0–100 score from data quality, calibration, execution, stability and evidence (sample size) — and which part is weakest Lessons What went wrong, what was done, did it work (§10) Plan vs actual Where the edge is lost between plan and fills (§9) Setups (cells) Expectancy heatmap by setup × month; lifecycle funnel (candidate → shadow → probation → active → paused → retired) Tweak & re-run Change a learning knob and replay (§12) Autonomy How much the system decides alone; change log with revert (§13) The frozen-model line is what makes progress honest: improvement is measured against \"what would have happened if the system had stopped learning\", on the same days and instruments."},{"d":8,"h":"12. Tweak & re-run (experiments)","a":"12-tweak-re-run-experiments","t":"You can change any learning knob and replay the last 12 months walk-forward before anything goes live. Knob Current (demo) Effect History window 18 months How much history each cell learns from Recency half-life 120 days Older trades count less; shorter adapts faster but is noisier Min trades to activate a cell 30 Evidence needed before a setup can trade Shrinkage prior 35 trades Pulls small samples toward the strategy average Breakout VIX gate 18 (or off) Regime gate for breakout cells Intraday stop 1.2 × ATR Initial stop for 5m/15m setups Selection threshold P(win) ≥ 52% Minimum calibrated probability to enter the plan Slippage model 8 bps Cost assumed in backtests Rules that keep experiments honest: 1. Same trades, same days (common random numbers): candidate and current model differ only by your change. 2. 12 out-of-sample folds ; the verdict needs ≥ 8 folds better. 3. Judged after the expected live gap : a cheaper slippage model cannot \"win\". 4. Total R matters : higher expectancy on far fewer trades (total R/year down 10%) is not \"better\". 5. Multiple-testing guard : the required improvement rises with the number of experiments in 30 days (0.02R + 0.006R × √trials). 6. Next step after \"better\" is shadow (paper alongside live for 30 trades); Apply needs your password, is audited, and is monitored for 60 trades with automatic rollback if live results fall below the old version."},{"d":8,"h":"13. Autonomy: less intervention, same control","a":"13-autonomy-less-intervention-same-control","t":"Level Plan tickets Learning changes Always asks you Advisory You approve every ticket All wait for you — Supervised (default) Tickets with P(win) ≥ threshold (default 58%) and every pre-trade check passing are auto-approved by the pre-open service at the cutoff; you review only the rest Pausing cells, exit re-selection, recalibration, regime gates applied automatically within guardrails Risk increases, new strategies, live execution, accounts Autonomous within limits All tickets inside risk limits are armed; daily digest with veto until the cutoff Shadow-tested challengers promoted automatically Same as above Guardrails at every level: one variable per change, out-of-sample proof, a weekly cap on automatic changes (default 3; more wait for you), 60-trade monitoring with automatic rollback, every change in the change log with one-click Revert , and password re-entry to raise the autonomy level. Auto-approved tickets are marked on the plan and in the audit log; the Decisions report compares them with your manual decisions so the threshold can itself be tuned from evidence."},{"d":8,"h":"14. Smart rules: from learned signals to a safer plan","a":"14-smart-rules-from-learned-signals-to-a-safer-plan","t":"Five learned rules sit between the scanner's candidates and tomorrow's plan, plus two feedback features. All run in the nightly pipeline without you; their state is shown on Plan review and Learning → Smart rules , and switching one off needs your password. Rule How it is learned What it changes 1 Grade on fills (§9) Executed prices from the broker (auto-journal); simulated fills in paper mode Every R, label and statistic; \"R plan\" kept alongside for the execution gap 2 Frozen-model benchmark (§11) Last year's model replayed on the same days Progress line on Learning, Today and the weekly digest 3 Lessons + automatic rollback (§10, §12) Monitors; 60-trade monitoring after every change A change that does worse live is rolled back without you (example L9) 4 Equity-curve throttle The system's own taken trades: equity vs its N-trade average (default 20) Risk × cut (default 0.5) while below; back to × 1 when above. Demo history: max drawdown −9.3R → −6.0R for 10% less total R 5 Market gate (no-trade days) Outcome of past trades by INDIA VIX level, breadth (% of tracked stocks above 20-DMA) and high-impact events (RBI, Budget) Reduced : half the tickets, risk × 0.75 · No-trade : no tickets (best candidates kept on reserve for reference) 6 Meta-labelling Second ML.NET model on graded trades: features of the signal → \"was it worth taking?\" Score < threshold (default 50%) → reserve; otherwise size × 0.5–1.5 7 Learned entry windows Walk-forward expectancy by entry hour per setup (backtest, thousands of trades) The ticket's validity window becomes the best hour (e.g. ORB 09:15–10:00) 8 Correlation-aware plan 60-day return correlation between tickets, open trades and holdings across accounts Correlation limit (default 0.6) with a better ticket or open trade → reserve (\"same bet\"); pre-trade checklist warns 9 Automatic loss tags Rules on MAE/MFE, entry time, regime, slippage, event calendar Tags on every loss (gap through stop, gave back open profit, against regime, late entry, high slippage, news/results, normal variance); a growing tag opens a lesson 10 Weekly learning digest Built by the weekly retrain service One summary: progress vs frozen model, what changed automatically, what needs you, what is being watched, why trades lost, focus for next week Honesty rules for these features: each rule's evidence (trade counts, R by bucket) is shown next to it; a rule that would remove more than half of all trades, or whose \"skipped\" trades are not worse than the \"taken\" ones over the last 100 trades, is flagged for review instead of being trusted blindly."},{"d":9,"h":"10 — Trade Selection & Allocation","a":"","t":"From dozens of candidates to the best max new entries per day (e.g. 3), fitted to each account."},{"d":9,"h":"1. Pipeline","a":"1-pipeline","t":"Scan scope: candidates come only from instruments in the baskets listed in scan scope (doc 06), each with its allowed styles/sides (e.g. MyLongTerm → swing BUY only). Every candidate carries its basket(s) so results can later be evaluated by basket."},{"d":9,"h":"Smart rules (learned, doc 09 §14)","a":"smart-rules-learned-doc-09-14","t":"Rule Effect on the plan Market gate Normal · reduced (half the tickets, risk × 0.75) · no-trade (no tickets; candidates kept on reserve) Learned entry window Intraday ticket validity window = the setup's best entry hour from walk-forward results Meta-labelling Score < meta.min take → reserve; otherwise size × 0.5–1.5 Correlation 60-day correlation corr.max with a better ticket or an open trade → reserve (\"same bet\") Equity-curve throttle Risk × throttle.cut while the system's equity is below its N-trade average Filtered tickets stay on the reserve list with the reason, and are graded like every other candidate."},{"d":9,"h":"2. Eligibility filters","a":"2-eligibility-filters","t":"Filter Default Cell status ACTIVE required Min calibrated P(win) 0.45 (for 1:2 exits) Min conservative expectancy +0.10R Min achievable R:R before obstacle 1.5 Min OOS sample 30 Max costs 0.10R Liquidity / events / F&O ban / surveillance excluded"},{"d":9,"h":"3. Merge duplicates","a":"3-merge-duplicates","t":"Group by (symbol, side); keep the highest conservative-E[R] ticket; add a confluence bonus when independent strategies/timeframes agree. Opposite sides for the same symbol: keep the stronger, or drop both if close."},{"d":9,"h":"4. Ranking","a":"4-ranking","t":"rank score = exp R lower + w conf·confluence + w regime·regime fit − w corr·correlation with book − w event·event risk"},{"d":9,"h":"5. Portfolio fill (greedy, constraints checked after each addition)","a":"5-portfolio-fill-greedy-constraints-checked-after-each-addition","t":"Constraint Default New entries per day 3 Open positions (incl. carried swing) 5 Total open risk 3% Per sector 2 Pair correlation (60-day) ≤ 0.70 Intraday / swing mix 2 / 2 Net long / short risk 2% / 2% One position per symbol yes Per basket (optional) e.g. max 2 from MyChoice Already held long-term Skip SELL setups on instruments in your holdings (configurable) count entries on: trigger (default): the plan may list up to max plan items (e.g. 5) conditional tickets; once 3 trigger, the rest are cancelled. plan mode limits the plan itself to 3."},{"d":9,"h":"6. Per-account allocation","a":"6-per-account-allocation","t":"1. Account sync provides funds, open positions and today's trades. 2. For each account: filter by allowed styles/instruments, drop symbols already held, apply the account's risk profile, size from its capital and lot sizes. 3. Mode replicate: every eligible account gets the same top tickets, sized individually. Mode distribute: ranked tickets are spread across accounts, no symbol duplicated. Default: replicate (decision Q4, 2026-10-09). 4. Cross-account limits: max accounts per symbol, max total risk across all accounts."},{"d":9,"h":"6b. Pre-trade checklist","a":"6b-pre-trade-checklist","t":"Each proposed ticket carries automatic checks — data quality, conflict with your holdings (e.g. a SELL on a stock you hold long-term), sector exposure, correlation with open trades and approved tickets , results within 3 days — shown on the ticket in Plan review (doc 15 §2). A failed check needs an explicit confirmation to approve."},{"d":9,"h":"6c. Human review","a":"6c-human-review","t":"The output of this pipeline is a proposed plan. You approve, modify or reject each ticket before the review cutoff; only approved tickets are armed at the pre-open check (doc 04 §4.2). Allocation goes only to accounts with the Trading role."},{"d":9,"h":"7. Day-level guards","a":"7-day-level-guards","t":"Daily loss limit ⇒ cancel remaining tickets; the market gate (learned from VIX, breadth and the event calendar) reduces or cancels the whole plan; the equity-curve throttle halves risk while the system is cold. Optional pre-open check (default 09:10, after the review cutoff and NSE pre-open price discovery): gap beyond trigger or gap invalidate atr ⇒ invalidate and promote from reserve."},{"d":9,"h":"8. Proving the selector (and your overrides)","a":"8-proving-the-selector-and-your-overrides","t":"Rejected candidates are graded nightly. Reports compare primary vs reserve vs rejected and \"top-1/3/5/all\" curves — showing whether ranking adds value and what max new entries per day should be. Your decisions are graded too: approved vs rejected vs lapsed vs modified tickets, compared with what the system proposed."},{"d":10,"h":"11 — Strategy Lab","a":"","t":"Submit your own strategy rules at any time; the system validates, tests and reports a verdict — no code changes, no restart."},{"d":10,"h":"1. Ways to submit","a":"1-ways-to-submit","t":"Channel How Rules editor React page with Monaco YAML editor, live JSON-Schema validation and autocomplete Form builder Pick indicators, conditions, stops, exits from menus → generates the same YAML Plain English Describe the idea to the assistant → it drafts YAML → you confirm Upload / CLI Upload a strategy file in the Lab, or run xd strategy test file.yaml — the file is imported into the database C plugin (advanced) Implement IStrategy for logic the DSL can't express; compiled and run in xd-sandbox (no network, resource limits) All channels produce one validated strategy spec, run by the same engine as built-in strategies."},{"d":10,"h":"2. Rules language (DSL)","a":"2-rules-language-dsl","t":"Declarative, safe (parsed and compiled to expression trees, never eval), look-ahead-proof (only closed bars; higher timeframes = last closed bar). \"Intraday: after 9:45 buy when a 15-min candle closes above VWAP with RSI(14) above 55 and 1-hour EMA20 above EMA50. Stop below last swing low. Target 1:2, or trail after 1R. Exit by 15:15. Mirror for shorts. Test 2022 to today on my MyChoice and Best stocks baskets.\" strategy: id: VWAP RSI TREND version: 1 style: intraday timeframes: [15m] sides: [BUY, SELL] SELL auto-mirrored unless a sell: block is given universe: { baskets: [MyChoice, \"Best stocks\"] } or instruments: [...] or a rule-based basket params: { rsi len: 14, rsi min: 55, swing lookback: 5 } setup: all: - time = \"09:45\" - tf(\"1h\").ema(20) tf(\"1h\").ema(50) - rsi(rsi len) rsi min trigger: all: - crosses above(close, vwap) entry: { type: at close } at close stop above high limit pullback stop: { type: swing low, lookback: swing lookback, buffer atr: 0.1 } exits: - { policy: FIXED RR, rr: [2.0] } - { policy: PARTIAL TRAIL, book pct: 50, t1 rr: 1.0, trail: { type: ATR, mult: 2.0 } } time rules: { last entry: \"14:30\", square off: \"15:15\" } filters: [not event day, min turnover] test: period: { from: 2022-01-01, to: today } method: walk forward walk forward simple split full period (exploration only) compare with: [baseline random, ORB] robustness: { param sensitivity: true, monte carlo: 1000, by year: true, by regime: true } Building blocks Examples Price & bars open high low close volume, close[1], prev day.high, today.open, or high(15) Indicators sma ema rsi atr adx macd bbands vwap supertrend highest lowest rel volume Multi-timeframe tf(\"1h\").ema(50), tf(\"1D\").close Conditions crosses above/below, comparisons, between, rising/falling(x,n), all/any/not Patterns inside bar, nr(7), gap pct, engulfing, pivot high/low(n) Context regime(), index.trend, vix pct, sector rs(n), day of week, is expiry day Stops fixed pct, atr mult, swing low/high, bar low/high, or opposite, level Exits Any policy from doc 08"},{"d":10,"h":"3. Pipeline","a":"3-pipeline","t":"Runs as Hangfire jobs in xd-worker; progress streamed to React via SignalR; indicator results cached. Full walk-forward: 10–60 min depending on universe, timeframes and exits."},{"d":10,"h":"4. Report","a":"4-report","t":"Section Content Verdict PASS / MARGINAL / FAIL with exact reasons (each gate ✓/✗) KPIs Trades, win rate, avg win/loss R, expectancy, profit factor, max drawdown, net ₹ after costs Best cells TF × side × exit with OOS expectancy and sample size By basket / instrument Same metrics per basket and per instrument — where the idea works and where it doesn't Charts Equity & drawdown, R histogram, MAE/MFE, by year, by regime, parameter heatmap, Monte Carlo fan Comparisons Random-entry baseline, existing strategies, index buy-and-hold Warnings Low samples, cost sensitivity, concentration, unstable parameters Trades Full list with chart replay Summary Plain English from the assistant, using report numbers only"},{"d":10,"h":"5. Guarding against \"test until it passes\"","a":"5-guarding-against-test-until-it-passes","t":"- Every variant recorded in a per-family test ledger ; thresholds tighten as variants grow. - Only walk-forward OOS can PASS; full period is exploration-only. - Promotion always passes through paper trading. - The assistant can run tests but cannot promote ."},{"d":10,"h":"6. Storage & reproducibility","a":"6-storage-reproducibility","t":"lab.strategies / lab.strategy versions (YAML + hash), lab.lab runs (data snapshot, config version, engine version), lab.lab results, lab.test ledger. The database is the only home of strategies (no repository folder); any version can be downloaded as a file and re-imported (ADR 0002)."},{"d":11,"h":"12 — Portfolio Monitoring","a":"","t":"Add your broker accounts and monitor every trade and holding : when it was added, current value, return %, XIRR, and totals — grouped by basket, account, strategy or sector."},{"d":11,"h":"1. Data sources","a":"1-data-sources","t":"Source What it provides When Dhan holdings & positions APIs Current holdings (delivery) and open positions (intraday/F&O) On sync (nightly + on demand + market hours) Dhan trade history API Every trade with date/time, price, quantity, side and full charge breakdown (paginated by date range) Nightly incremental; one-time backfill Dhan ledger API Cash credits/debits (funds added/withdrawn, dividends, charges) Nightly CSV import Older trades (before API history / other brokers), contract-note or tradebook exports On demand Manual entry Corrections, off-platform transactions On demand Corporate actions Splits, bonuses, dividends Nightly Prices Live quotes for open trades & holdings; EOD close for valuation (doc 05 §5) Market hours / EOD History depth (decision Q5): start with what Dhan's trade-history API returns; older lots come from CSV / contract-note import (P2-03). Computed-vs-broker holdings are reconciled nightly, so gaps in history show up as differences."},{"d":11,"h":"2. Domain model","a":"2-domain-model","t":"- Transaction — immutable record (source: broker / CSV / manual; charges attached). - Lot — each buy creates a lot; sells consume lots FIFO (matches Indian practice) → realised P&L per lot. - Position — open quantity, average cost (incl. charges), first-added date, linked plan ticket (if any). - Valuation — market value at a time; a daily snapshot after close builds the portfolio value history. - Cash flow — dated money in/out used for XIRR."},{"d":11,"h":"3. Metrics","a":"3-metrics","t":""},{"d":11,"h":"Per position / trade","a":"per-position-trade","t":"Metric Definition Added on Date/time of first buy (and of each add) Days held Calendar days since first buy (or until exit) Quantity, avg cost Open quantity; average cost including charges LTP, market value Live or last close price × quantity Unrealised P&L (₹, %) Market value − remaining cost Realised P&L (₹) From FIFO-closed lots, net of charges Total return % (Realised + unrealised + dividends) / total invested Day change (₹, %) vs previous close XIRR Annualised return from dated cash flows (§4) CAGR For holdings 1 year Weight % Share of portfolio (or bucket) value System trade info Strategy, cell, entry plan, R-multiple, stop/target distance (if from a plan ticket)"},{"d":11,"h":"Per group (basket / bucket / account / strategy / sector / total)","a":"per-group-basket-bucket-account-strategy-sector-total","t":"Invested · current value · realised · unrealised · total return % · XIRR · day change · number of open positions · win rate & expectancy of closed trades · benchmark XIRR (same cash flows invested in Nifty 50) and alpha (XIRR − benchmark XIRR) · max drawdown of the group's value history."},{"d":11,"h":"4. XIRR","a":"4-xirr","t":"Cash flows: each buy = −(amount + charges); each sell = +(amount − charges); dividends = +amount; plus the terminal value = +current market value on the valuation date. XIRR is the rate r where Σ CFᵢ / (1 + r)^((dᵢ − d₀) / 365) = 0 - Solved with Newton–Raphson, falling back to bisection if it doesn't converge (Excel-compatible results). - Computed for any set of cash flows: one trade, a position, a bucket, a basket, an account, the total. - Short periods: annualising a few days' return gives misleading numbers; below min days for xirr (default 30) the UI shows absolute return and marks XIRR as \"short period\". - Example: buy ₹1,00,000 on 1 Jan; add ₹50,000 on 1 Apr; value ₹1,72,000 on 31 Dec → XIRR ≈ 16.1% (absolute return 14.7%)."},{"d":11,"h":"5. Grouping: baskets vs portfolio buckets","a":"5-grouping-baskets-vs-portfolio-buckets","t":"Concept Overlap Use Instrument baskets (doc 06) An instrument can be in many baskets Analysis lens — totals not additive Portfolio bucket Each position belongs to exactly one bucket Additive view — bucket totals sum to the portfolio - A position's bucket defaults to the instrument's primary basket (e.g. MyLongTerm) and can be overridden per trade — e.g. the same stock bought for long-term (bucket MyLongTerm ) and for a swing trade (bucket Trading ) is tracked as two positions with separate lots, returns and XIRR. - System-plan trades default to bucket Trading (configurable). Views: tree — Total → Account → Bucket → Position → Lots/Transactions; pivot — rows by bucket, basket, account, strategy or sector with the metrics in §3."},{"d":11,"h":"6. Live updates","a":"6-live-updates","t":"What Update method Frequency Open intraday & swing positions, armed tickets Dhan WebSocket (active set) Real-time Long-term holdings Dhan quote API (up to 1,000 instruments/request) Every holdings refresh minutes (default 5) Portfolio snapshot EOD official close Daily after close The React Portfolio screen receives updates via SignalR; values recalculate incrementally."},{"d":11,"h":"7. Alerts","a":"7-alerts","t":"Price reaches a plan's stop/target level · swing position at max holding (5 sessions) · results date within N days for a holding · position weight max position weight pct · bucket drawdown threshold · large day move on a holding · data or token issue for an account."},{"d":11,"h":"8. Link to the trading system","a":"8-link-to-the-trading-system","t":"- Positions created from plan tickets keep plan item id → strategy, cell, R-multiple and grading. - Trades not matching any plan are tagged discretionary ; their results are reported separately (and in the discipline report). - Long-term holdings are not managed by the system's exits unless you assign a strategy/exit to them."},{"d":11,"h":"9. Data model (portfolio schema)","a":"9-data-model-portfolio-schema","t":"Table Key columns accounts (in trading) id, broker, mode, profile transactions id, account id, instrument id, type, ts, qty, price, charges (JSON), source, external id, bucket id, plan item id lots id, transaction id, open qty, cost per unit, opened at, closed at lot closures lot id, sell transaction id, qty, realised pnl positions account id, instrument id, bucket id, qty, avg cost, first added at, status buckets id, name, default basket id cash flows id, account id, ts, amount, kind (deposit/withdrawal/dividend/charge/trade) valuations daily date, account id, bucket id, position id, market value, invested, realised, unrealised corporate action adjustments instrument id, ex date, ratio, applied to lots"},{"d":11,"h":"10. Portfolio screen (React)","a":"10-portfolio-screen-react","t":"- Account tiles (one per Portfolio account + \"All accounts\"): value, unrealised P&L (₹, %), day change, XIRR, open positions, realised P&L, top holding and its weight, number of open action items — click to focus the whole page on that account. - Action center: positions that need a decision, per account — below cost, large gain, overweight, sector concentration, max holding exceeded, results due, long-term soon, lagging Nifty, not in a basket — with Open / Set alert / Add to basket / Snooze / Done (doc 15 §3). - Header tiles: total value · invested · total P&L (₹, %) · XIRR · day change · benchmark XIRR / alpha. - Group by: Bucket · Basket · Account · Strategy · Sector · None — with tree-grid (expand to lots and transactions) and column chooser. - Charts: allocation by group, sector exposure stacked by account, portfolio value vs the same cash flows in Nifty 50, XIRR by group. - Price alerts: create from the Action center or a position; evaluated by the services; list in an Alerts panel. - Position drawer: transaction timeline, price chart with buy/sell markers, lots, alerts, linked plan ticket. - Filters: date range (for realised results), account, bucket, basket, status (open/closed), source. - Exports: CSV/Excel of positions, transactions and realised P&L. Out of scope for now: tax reports (STCG/LTCG statements) — the lot data supports adding them later."},{"d":12,"h":"1. Screens","a":"1-screens","t":"Screen Purpose Key components Login / lock screen One centred panel: about + non-sensitive service status (no balances before sign-in) on the left, form on the right. Show/hide password, Caps Lock warning, attempts left, live lockout countdown. Idle or manual lock keeps the user and asks only for the password (\"Welcome back · Unlock\"), and survives a page reload; password re-entry for sensitive actions Form, status strip Today Plan status, live open positions & P&L, armed tickets, alerts, briefing, services health KPI tiles, ticket cards, live price panel (SignalR) Plan review Approve / modify / reject proposed tickets before cutoff; reserve list; limits check Ticket cards with chart, bulk approve, countdown to cutoff Suggestions AI / engine suggestions inbox (track instrument, basket changes, promotions) Cards with reason & evidence, accept / reject Portfolio All holdings/trades across accounts: added date, value, return %, XIRR; group by bucket / basket / account / strategy / sector (doc 12) Header tiles, tree-grid, treemap, value-vs-benchmark chart, position drawer Instruments Master-list search, tracked instruments, coverage & quality, bulk actions (doc 06) Faceted search, Data Grid, chips Baskets Create/edit manual & rule-based baskets, members, basket performance & benchmark Drag & drop, rule builder with live preview, comparison charts Trade Plan Tickets per account with reasons, reserve list, pre-open check Ticket cards with Lightweight Charts (entry/stop/target overlays), account switcher Journal Taken/skipped/modified (auto-matched), notes, tags Data Grid, trade replay chart Reports Landing Overview dashboard with auto-insights, report catalogue, multi-basket comparison , pivot builder; common filters incl. multi-select baskets ECharts, heatmaps, Data Grid, export Strategy Lab Editor/form, runs queue, verdict report, version compare Monaco + schema, progress via SignalR Learning How the system improves: journey (live vs frozen model vs plan prices, with problem/fix markers), lessons (what went wrong → fix → result), plan vs actual execution gap, setups (cell heatmap & lifecycle), smart rules (market gate, equity throttle, meta-labelling, entry windows, correlation), tweak & re-run experiments, autonomy settings & change log with monitoring/rollback, weekly digest (doc 09 §9–§14) ECharts, lesson cards, knobs + replay progress, change log Data & Import CSV upload/preview/commit/undo, import profiles, coverage per timeframe, EOD fetch runs, quality issues Dropzone, preview grid, coverage heatmap Accounts List + detail with tabs (Overview, Roles, Trading, Portfolio, Data, Connection, Activity), role matrix, shared risk profiles, add-account wizard, data failover (doc 04 §1.1) Master-detail, tabs, wizard Data quality Every tracked instrument: coverage, validation status, aggregates vs 1-minute, official-daily match, repair (doc 05 §10b) Status table, inspect drawer with stored-vs-recomputed table Config Trading config editor, validate, diff, activate, history Monaco YAML + JSON Schema, diff view Assistant Chat over your data; answers show numbers, query and chart Streaming chat panel Services Every background service: editable schedule (type, time, days, window, interval, run-after), retries, timeout, catch-up, parameters; dependency checks; trading-day timeline; run now, pause, history Status table, configure dialog, timeline Audit Logins, configuration changes, approvals, service actions Filterable log Every analytic screen has a lens selector — All trades · By basket · By instrument · By individual trade · By strategy · By account (doc 06 §4) — plus a common filter bar: date range · source (backtest / paper / live) · account · basket · style · strategy · timeframe · side · exit policy · regime · symbol · sector · plan status · discretionary vs system trades."},{"d":12,"h":"1b. Clickable prototype","a":"1b-clickable-prototype","t":"A working front-end prototype of these screens lives in prototype/index.html (open it directly in a browser — offline, demo data, no backend; services and the live feed are simulated in the browser). It demonstrates the login (demo credentials prefilled); Accounts (list/detail tabs, role matrix, risk profiles, wizard, data failover); plan review with approve / modify / reject, the pre-trade checklist and auto-approval at the cutoff ; suggestions inbox; portfolio with per-account tiles, Action center, price alerts, XIRR and animated grouping; instruments (one scrollable grid with sticky header and symbol column) & baskets; CSV import with aggregation; the Data quality window; the Learning screen (journey, lessons with loss tags, plan vs actual with fills ledger, setups, smart rules, tweak & re-run, autonomy, weekly digest); live tickets filled with simulated slippage and graded on fills; Reports (overview with auto-insights, basket comparison, pivot and 10 more reports); Strategy Lab; Services with schedule configuration, dependency checks, timeline and catch-up; settings with password re-entry; the audit log — responsive from phones to 4K monitors, light and dark. Visual language (carried into the React app): Inter font and a standard, calm palette (Tailwind slate/gray neutrals with one indigo accent; green/red/amber only for meaning), a light sidebar with a soft colour-tinted icon per screen, tiles with tinted icons and count-up numbers, collapsible cards, animated dialogs/drawers/toasts (respecting reduce motion ), light and dark themes, and scrollable data grids with sticky headers instead of pagination. In MUI this is one theme object (palette, shape, typography) shared by every screen. Navigation for speed: a command palette ( ⌘K / Ctrl K or / ) searches pages, Learning tabs, actions (run nightly, digest, lock, theme), baskets and every instrument (opens its chart drawer); g + letter jumps to a page (g t Today, g r Plan review, g p Portfolio, g l Learning …); ? lists all shortcuts; the browser tab title shows the current screen."},{"d":12,"h":"1c. Reports experience","a":"1c-reports-experience","t":"- Landing = Overview: KPI tiles (trades, win rate, expectancy, total R & ₹, profit factor, max drawdown), auto-insights in plain sentences (doc 15 §6), equity & drawdown, monthly results, strategy × timeframe heatmap, expectancy by basket, R distribution, win rate by weekday. - Left-hand catalogue: Overview · Basket comparison · Strategies · Exit policies · Side & regime · Calendar & time · MAE/MFE · Calibration · Instruments · Accounts · Decisions · Pivot builder · Trade list. - Global filters: date range with presets, multi-select baskets , side, style, account. - Basket comparison: choose 2+ baskets → side-by-side KPIs (trades, win rate, expectancy, total R, profit factor, max drawdown, net ₹, best strategy, buy-and-hold return), overlaid cumulative-R curves, expectancy by strategy per basket, basket × side and basket × style heatmaps. - Pivot builder: any two dimensions (strategy, timeframe, basket, side, style, exit, regime, account, instrument, sector, weekday, month, decision) × metric (expectancy, total R, win rate, trades, profit factor)."},{"d":12,"h":"1d. Responsive design (all monitors)","a":"1d-responsive-design-all-monitors","t":"Width Layout < 480 px (phones) Single column, 2-up KPI tiles, larger touch targets, off-canvas navigation 481–860 px (small tablets) Single column, off-canvas navigation, wrapping filters 861–1200 px (tablets / small laptops) Icon-only sidebar (expandable), 1–2 column grids 1201–1679 px (laptops / desktops) Full sidebar (collapsible), 2–3 column grids 1680–2559 px (large / QHD) No max-width cap, 2-column plan tickets, taller charts, larger base font ≥ 2560 px (4K / ultrawide) Up to 4 columns of tickets/cards, larger charts and font Rules: no horizontal page scroll at any width (wide tables scroll inside their card), fluid grids (auto-fit/minmax), charts resize with their containers, sidebar state remembered per device."},{"d":12,"h":"2. Report catalogue","a":"2-report-catalogue","t":"Report Answers Visuals R1 Next-day plan What to do tomorrow and why Ticket cards, mini-charts, reserve list R2 Daily scorecard How did yesterday's plan do R per ticket, trigger hit/missed R3 Performance overview Am I making money Equity (R, ₹), underwater drawdown, KPI tiles R4 Strategy × timeframe matrix What works Expectancy heatmap, split by side R5 Exit-policy comparison 1:2 vs 1:3 vs trail vs pyramid per cell Grouped bars on identical entries R6 Side analysis Longs vs shorts Side-by-side KPIs and equity R7 Regime analysis What works in which market Cell × regime heatmap, regime timeline R8 MAE/MFE Stops too tight? targets too greedy? Scatter, histograms with target markers R9 R distribution Payoff shape Histogram R10 Calendar & time-of-day When it works Calendar heatmap, weekday/hour/expiry bars R11 Symbol & sector Where it works Treemap / ranked bars R12 Calibration Are probabilities honest Reliability diagram R13 Selector effectiveness Does top-3 beat the rest Primary/reserve/rejected, top-k curves R14 Backtest vs paper vs live Does reality match research Overlaid equity, slippage distribution R15 Monte Carlo risk Expected drawdowns Fan chart, percentiles R16 Learning changelog What changed and why Timeline R17 Account comparison How each account performs Per-account KPIs and equity R18 Data quality Can tonight's data be trusted Check status, flagged symbols R19 Discipline Am I following the plan Taken vs recommended, cost of deviations in R R20 Basket comparison Which basket works best, for which style/strategy Side-by-side KPIs, basket × strategy heatmap, vs basket buy-and-hold & Nifty R21 Instrument scorecard Which instruments consistently work / fail Ranked table, sparkline equity per instrument R22 Portfolio overview What is my portfolio worth and how is it doing Value, invested, P&L, XIRR, alpha; allocation by bucket/basket/sector R23 Portfolio returns Returns and XIRR by group over time XIRR by group bars, value vs benchmark, drawdown R24 Realised P&L What did closed trades make FIFO realised P&L by period / bucket / instrument, charges breakdown R25 Data coverage Do I have complete data for every tracked instrument and timeframe Coverage heatmap, import & EOD history R26 Decisions review Do my approvals/rejections add value vs the system's proposal Approved vs rejected vs lapsed outcomes in R R27 Basket comparison Which basket works best and why Multi-select baskets: KPIs, overlaid equity, strategy × basket, buy & hold R28 Pivot Any dimension × any dimension Heatmap with metric selector R29 Data quality Is every timeframe correct Validation status, stored vs recomputed R30 Learning journey Is the system actually getting better Weekly expectancy: live vs frozen-model counterfactual vs plan prices; problem→fix bands; cumulative uplift R31 Lessons What went wrong and how it was fixed Lesson cards (problem → diagnosis → fix → result), before/after metric, walk-forward evidence R32 Execution gap Where the edge is lost between plan and fills Waterfall (plan → slippage → missed → overrides → charges → actual), by strategy and month R33 Experiments Which settings were tried and what they did Experiment history with Δ expectancy, folds better, verdict, status R34 Loss tags Why trades lose Tag counts and R lost by tag, linked lessons R35 Smart-rule evidence Is each rule still earning its place Throttle: equity with/without; meta: R taken vs skipped; gate: R by VIX/breadth bucket; windows: R by hour; correlation matrix Standard KPIs: trades · win rate · avg win/loss R · expectancy · profit factor · total R · net ₹ after costs · max drawdown (R, %) · Sharpe/Sortino · avg holding · exposure · longest loss streak. Drill-down: heatmap cell → cell detail (equity, exit comparison, MAE/MFE, regime split) → trade list → trade replay (entry, stop, target, trail path, exit reason, feature snapshot)."},{"d":12,"h":"3. Exports & delivery","a":"3-exports-delivery","t":"Plan: page + PDF/HTML. Portfolio: CSV/Excel of positions, transactions and realised P&L. Any report: CSV/Excel. Weekly review pack (PDF): R3, R4, R5, R12, R13, R16 + assistant summary. Notifications appear in-app (SignalR); optional external channel only if you enable one."},{"d":12,"h":"4. Implementation notes","a":"4-implementation-notes","t":"- Report queries live in the .NET Reporting module; heavy aggregates via SQL materialised views refreshed nightly; responses are chart-ready series. - Lightweight Charts for anything price-based; ECharts for analytics. - The SPA is a PWA so it can be \"installed\" on your phone (LAN access)."},{"d":13,"h":"1. Roles","a":"1-roles","t":"Job Who Why Signals, stops, targets, sizes Deterministic .NET engine Exact, testable P(win), expected R Gradient-boosted trees in ML.NET (trained & scored in .NET) Measurable accuracy Exit choice, ranking, selection Deterministic rules on learned statistics Auditable Daily briefing, weekly review LLM Language summarisation Questions about your data LLM + read-only tools Numbers come from tools Draft strategy rules for the Strategy Lab LLM (you confirm; tests decide) Faster research Propose hypotheses (one variable) LLM (engine validates) Research help Suggest instruments / basket changes / next-day focus LLM + engine evidence → suggestions inbox; you accept or reject Human in the loop Extract data from filings/announcements (later) LLM (validated) Unstructured text Predict prices / make trade decisions Never Unverifiable"},{"d":13,"h":"2. Setup","a":"2-setup","t":"Component Choice Model server xd-llm: llama.cpp server (image quay.io/ramalama/ramalama, pinned) on the libkrun Podman machine with GPU (Vulkan), OpenAI-compatible API; started on demand (ADR 0005) Main model Qwen3-30B-A3B Q4 K M (MoE, ≈ 18.6 GB; measured 41 tok/s at 8K context in the container); alternate gpt-oss-20b (12 GB) — final pick by the eval set (§5). Context 16K default, 32K supported; keep prompts ≤ 8K tokens Small model none — the MoE main model is faster than a dense 8B; a dense 14B was rejected (first token 27 s) Embeddings nomic-embed-text or bge-m3 (for search over notes/docs) Fallback Host-native llama.cpp (Metal) — measured 1.1–1.4× faster generation and 1.4–1.8× faster prompt reading than the container, loads in 5–10 s; endpoint change only. The container meets the speed thresholds, so it stays the default Model choice is config; select by our eval set, not leaderboards."},{"d":13,"h":"3. Integration (.NET)","a":"3-integration-net","t":"- xd-api assistant endpoint uses Microsoft.Extensions.AI with tool calling; streams to React. - Tools are served by xd-mcp (ModelContextProtocol C SDK) over a read-only DB role : list tables, describe table, run sql(read only, row limit), get report(type, filters), get plan(date, account), get cell(key), get portfolio(group by, as of), get basket(name), make chart(spec), lab validate(yaml), lab run(yaml). - Guardrails: numbers only from tool results; no write tools except lab run; no promotion; no config changes (only proposed diffs you apply in the Config screen); prompts and tool calls logged in ai. ; broker secrets never in context. If the LLM is down, the nightly plan is unaffected."},{"d":13,"h":"4. Features","a":"4-features","t":"1. Daily briefing (≤ 300 words): regime, the tickets with one-line rationale, risks, system changes. 2. Ask your data : \"Expectancy of 15m SELL setups in high-vol regimes in 2025?\" → query + numbers + chart. Also portfolio and baskets: \"XIRR of MyLongTerm vs Nifty this year?\", \"Which basket worked best for 15m setups?\" 3. Strategy drafting : English idea → DSL YAML → validation → you confirm → Lab run → summary. 4. Hypothesis proposals for the learning loop (doc 09 §5). 5. Event flags (later): classify announcements for the event-risk filter."},{"d":13,"h":"5. Eval set (re-run on every model/prompt change)","a":"5-eval-set-re-run-on-every-modelprompt-change","t":"Task Test Pass Data questions 30 questions with known answers ≥ 90% exact numbers Briefing 10 historical plans No numbers absent from input; all tickets covered Strategy drafting 10 ideas Valid DSL; matches intent on review Event flags 200 labelled announcements Precision on \"material\" ≥ 80%"},{"d":13,"h":"6. Hermes Agent (Nous Research) — decision","a":"6-hermes-agent-nous-research-decision","t":"What it is: open-source (MIT) always-on agent: persistent memory, self-written skills, built-in cron, MCP client, messaging gateways (Telegram, WhatsApp…), works with local OpenAI-compatible models. Decision: not part of the core. Build the built-in assistant first. Evaluate Hermes in Phase 9 as an optional front-end (phone access, scheduled summaries) connected only to xd-llm and xd-mcp. Why cautious: a third-party review (Sept 2026) cites 44 published CVEs including high-severity remote-code-execution and supply-chain issues, and an audit found unrestricted shell and credential-file access in default config; self-written skills/memory can persist errors or injected instructions; it needs ≥ 32–64K context. If adopted, mandatory hardening: own image from a pinned release (no curl bash); shell, browser, web-search, file-system and media tools disabled; only xd-mcp registered; no secrets mounted; egress only to xd-llm/xd-mcp; skills git-tracked and memory reviewed weekly; messaging off by default; monthly CVE check. PoC pass criteria: hardened container works with the local model · ≥ 90% on the data-question eval · 8/10 strategy drafts valid · cron summary delivered 5 days running · prompt-injection probe (malicious journal note) causes no unintended tool calls · runs alongside the core stack without memory pressure · clear benefit over the built-in assistant."},{"d":14,"h":"15 — Smart Insights & Automation","a":"","t":"How xDrishti turns data into decisions you can act on , for both trading and portfolio management — without taking decisions away from you. Everything here is deterministic rules and statistics evaluated by the services; the LLM only explains (doc 14)."},{"d":14,"h":"1. Where the system is \"smart\"","a":"1-where-the-system-is-smart","t":"Area Smart behaviour Where you see it Next-day plan Learned setups, calibrated probabilities, top-N selection (docs 09–10) Plan review Pre-trade checklist Every proposed ticket is checked against your holdings, sector limits, results dates and data quality Plan review (per ticket) Portfolio Action center Rules flag positions that need a decision, per account Portfolio Price alerts Your alerts are watched by the services, not your browser Portfolio, notifications Data quality gate Instruments failing validation are skipped by the nightly scan and flagged on tickets Data quality, Plan review Report auto-insights Best/worst strategy, basket gap, side bias, best exit, regime, weekday, calibration — in plain sentences Reports → Overview Schedule intelligence Dependency and timing checks; run-after chains; catch-up after sleep; automatic data failover Services, Accounts Decision feedback Your approvals/rejections are graded against the system's proposal Reports → Decisions Auto-approval (autonomy) Tickets above your probability threshold with every check passing are approved at the cutoff Plan review, Learning → Autonomy Lessons & execution feedback Problems detected by monitors become lessons with a fix and a measured result; grading uses real fills Learning Tweak & re-run Change a learning knob and replay 12 months walk-forward with honest comparison rules Learning → Tweak & re-run Smart rules Market gate (no-trade days), equity-curve throttle, meta-labelling, learned entry windows, correlation-aware plan (doc 09 §14) Plan review banner & tickets, Learning → Smart rules Graded on fills Live and paper trades graded at executed prices; R at plan prices kept for the execution gap Today, Reports → Trade list, Learning → Plan vs actual Automatic loss tags Every loss tagged (gap, gave back profit, against regime, late entry, slippage, news) and linked to a lesson Learning → Lessons, Reports → Trade list Weekly learning digest One summary instead of daily approvals Today, Learning, notification"},{"d":14,"h":"2. Pre-trade checklist (per proposed ticket)","a":"2-pre-trade-checklist-per-proposed-ticket","t":"Check Rule Result Data quality Instrument's latest validation status ✗ fail blocks one-click approval (you can still approve with a confirmation, and it is recorded) Holdings conflict SELL ticket on an instrument you hold long in any account; or an open trade already exists ⚠ Sector exposure Open trades + already-approved tickets in the same sector ≥ profile limit ⚠ Event risk Quarterly results within 3 days ⚠ (later) Correlation 60-day correlation with open trades 0.7 ⚠ Checks are shown on the ticket card; \"approved despite\" reasons are stored and appear in the Decisions report."},{"d":14,"h":"3. Portfolio Action center","a":"3-portfolio-action-center","t":"Evaluated per account by the Price alerts & action center service (every minute in market hours, and after each sync). Thresholds are configurable (Settings → Action center thresholds). Rule Default trigger Suggested action Below cost Unrealised ≤ −10% (high if ≤ −20%) Hold with a stop alert, average only if the thesis holds, or exit Large gain Unrealised ≥ +25% Book part of the gain or set a trailing-stop alert Overweight Weight max(15%, 1.5 × equal-weight share) of the account (≥ 3 positions) Trim or rebalance Sector concentration One sector 35% of the account Diversify Max holding exceeded Trading-bucket position older than the 5-session limit Exit per plan rules Results due Results within 7 days Decide before the event Long-term soon Profitable holding becomes 12 months within 30 days Check tax impact before selling early (informational only) Lagging Nifty Held 180 days and XIRR more than 10 pp below the same cash flows in Nifty 50 Review the thesis / replace Not in a basket Holding not assigned to any basket Assign for basket analytics Each item offers Open , Set alert , Add to basket , Snooze 7 days or Done ; every action is audited. Per-account tiles on the Portfolio page show value, P&L, XIRR, day change, top holding and the number of open action items, so you can focus on the account that needs attention."},{"d":14,"h":"4. Price alerts","a":"4-price-alerts","t":"- Conditions: price at or below / at or above a level (quick presets ±5/10/20%), optional note. - Evaluated by services: alert symbols join the polled set (or the live set if already streamed); triggered alerts create a notification and audit entry. Alerts survive logout and browser close. - Later: indicator alerts (e.g. close below 50 DMA), trailing alerts, alert on basket-level drawdown."},{"d":14,"h":"5. Data quality gate","a":"5-data-quality-gate","t":"After every end-of-day fetch the Data validation service re-checks the last N sessions of every tracked instrument (doc 05 §10b). Results drive: - a data quality score (pass = 1, warning = ½) shown on the Data quality page and Today, - per-instrument fail-closed : failing instruments are skipped by the nightly scan and flagged on any ticket, - one-click repairs (re-fetch the day, refresh aggregates) followed by automatic re-validation."},{"d":14,"h":"6. Report auto-insights","a":"6-report-auto-insights","t":"Computed from graded trades for the current filters (minimum 15 trades per group): best and weakest strategy (pause candidate), best vs worst basket gap, long vs short bias, best exit policy, most/least favourable regime, best/worst weekday, calibration quality (predicted vs actual win rate). The local LLM can turn these into the weekly review text; numbers always come from the report engine."},{"d":14,"h":"7. Schedule intelligence","a":"7-schedule-intelligence","t":"- Rules checked on every schedule change: pre-open check after the review cutoff and before 09:15 (and ideally after NSE pre-open price discovery 09:08); EOD fetch after 15:35; nightly pipeline after EOD fetch and portfolio sync; live window covering the session; no backups in market hours; no circular \"run after\" chains. Errors block saving; warnings are shown. - Run-after chains (e.g. data validation after EOD fetch; AI suggestions after the nightly pipeline). - Catch-up of missed runs after the machine wakes; automatic data failover to the standby Data account."},{"d":14,"h":"8. Further smart features (roadmap candidates)","a":"8-further-smart-features-roadmap-candidates","t":"Idea Value Rebalancing to basket target weights Suggested buy/sell list to bring long-term baskets back to targets Regime-aware sizing Scale risk per trade down in high-volatility regimes (learned) Correlation clusters Avoid hidden concentration across accounts What-if on approvals Show portfolio heat / sector exposure if you approve a ticket Post-trade review prompts Journal questions after each closed trade; discipline score Tax-lot aware selling Prefer lots that minimise short-term gains (informational) Earnings & corporate-action calendar Feed event filters and alerts Dividend tracking in XIRR Dividends from ledger as cash flows Volatility-scaled position sizing Size so each trade risks the same rupees after slippage, capped by liquidity (capacity)"},{"d":15,"h":"1. Two kinds of configuration","a":"1-two-kinds-of-configuration","t":"Kind Where Edited via Examples Trading config Stored versioned in config.config versions (seed: built-in defaults shipped with the backend) React Config screen (Monaco + JSON Schema, diff, activate) Scan scopes, data, strategies, exits, risk, accounts, learning, selection, portfolio Catalog data Database tables, edited in dedicated screens Instruments, Baskets, Import screens Tracked instruments, baskets & members, CSV import profiles (YAML seed optional) Infrastructure settings .NET appsettings.json + environment + Podman secrets Files in deploy/ Connection strings, endpoints, ports, log levels Rules: JSON Schema validation before activation; every run records the active config hash; secrets are referenced by name only (Keychain → Podman secrets)."},{"d":15,"h":"2. Trading config (v1 defaults, illustrative)","a":"2-trading-config-v1-defaults-illustrative","t":"version: 1 market: exchange: NSE timezone: Asia/Kolkata session: { open: \"09:15\", close: \"15:30\" } goals: target expectancy R: 0.20 max drawdown pct: 8 max drawdown action: halt and review Accounts and their roles are managed in the Accounts screen (stored in DB, password re-entry); shown here as seed. accounts: - id: dhan main broker: dhan credentials: dhan main Keychain item name — never the secret itself roles: data: { enabled: true, primary: true } trading: { enabled: true, mode: paper, profile: standard, styles: [intraday, swing], instruments: { intraday: [EQ MIS], swing buy: [EQ CNC], swing sell: [FUT] }, capital: { source: broker funds, cap: 1000000 } } portfolio: { enabled: true, default bucket: Trading } - id: dhan longterm broker: dhan credentials: dhan longterm roles: portfolio: { enabled: true, default bucket: MyLongTerm } - id: dhan swing broker: dhan credentials: dhan swing roles: data: { enabled: true, standby: true } failover if primary token/subscription fails trading: { enabled: true, mode: manual live, profile: conservative, styles: [swing], capital: { source: fixed, amount: 300000 } } portfolio: { enabled: true, default bucket: Trading } data provider: { reconcile with: nse files } market data always from the primary Data account access: idle timeout min: 30 absolute timeout h: 12 lockout: { attempts: 5, minutes: 15 } step up for: [account roles, credentials, config activation, execution, data deletion] approvals: plan review cutoff: \"09:05\" unreviewed policy: lapse lapse arm top n allow modifications: [reduce size, tighten stop, change account, swap with reserve] suggestions: { expiry days: 3, snooze after reject days: 14 } risk profiles: shared; edited on Accounts → Risk profiles; accounts may override values standard: risk per trade pct: 0.5 max capital per trade pct: 25 max new entries per day: 3 max open positions: 5 max total risk pct: 3.0 max per sector: 2 max pair correlation: 0.70 max intraday: 2 max swing: 2 daily loss: { R: 2, pct: 1.5 } weekly loss: { R: 5, action: halve size } conservative: inherits: standard risk per trade pct: 0.25 max new entries per day: 2 max open positions: 3 daily loss: { R: 2, pct: 1.0 } allocation: mode: replicate replicate distribute max accounts per symbol: 2 max total risk pct all accounts: 3.0 scan scope: which baskets the nightly plan scans (baskets are managed in the UI) - { basket: \"Best stocks\", styles: [intraday, swing] } - { basket: \"MyChoice\", styles: [intraday] } - { basket: \"MyLongTerm\", styles: [swing], sides: [BUY] } context indices: [NIFTY 50, NIFTY BANK, INDIA VIX] filters: { min price: 100, min avg turnover cr: 50, exclude: { fno ban: true, asm gsm: true, results within days: 2 } } catalog: auto track imported instruments: true master refresh: daily basket membership mode default: current current as of (for reports) data: base resolution: 1m csv import: inbox path: data/inbox watch inbox: true default profile: my 1min files precedence: [dhan eod, csv, live] which source wins on overlap conflict tolerance pct: 0.1 eod fetch: time: \"15:50\" lookback gap days: 5 backfill years on track: 5 Dhan intraday history limit 5 years throttle requests per sec: 5 aggregation: timeframes: [5m, 10m, 15m, 30m, 1h, 1D, 1W, 1M] session anchor: \"09:15\" daily source: official official derived keep partial last bar: true min completeness pct: 80 adjust: { splits bonus: true, dividends: false } quality: { max missing bar pct: 2.0, spike atr mult: 8, stop if index bad: true } live: enabled: true session: { start: \"09:00\", end: \"15:35\" } active set: { open positions: true, armed tickets: true, context indices: true, pinned baskets: [] } ws mode: quote ticker quote full max ws instruments: 200 holdings refresh minutes: 5 persist live bars: true portfolio: sync: { time: \"16:30\", trade history backfill from: 2023-01-01 } lot method: fifo include charges in cost: true default bucket for plan trades: Trading buckets: [Trading, MyLongTerm, MyChoice] benchmark: NIFTY 50 min days for "},{"d":15,"h":"3. Infrastructure settings (appsettings.json excerpt)","a":"3-infrastructure-settings-appsettingsjson-excerpt","t":"{ \"ConnectionStrings\": { \"Db\": \"Host=xd-db;Database=xdrishti;Username=xd app\" }, \"Llm\": { \"Endpoint\": \"http://xd-llm:8080/v1\" }, \"Models\": { \"Path\": \"/models\" }, // ML.NET model files \"Seq\": { \"ServerUrl\": \"http://xd-seq:5341\" }, \"Secrets\": { \"Path\": \"/run/secrets\" } } Passwords and broker keys are read from /run/secrets/ (Podman secrets) via the KeyPerFile provider."},{"d":15,"h":"4. Most-used settings","a":"4-most-used-settings","t":"Setting Meaning Default risk profiles. .max new entries per day Max new trades/day per account 3 risk profiles. .max open positions Max open trades per account 5 risk profiles. .risk per trade pct Size of 1R 0.5% styles.swing.max holding sessions Max holding 5 allocation.mode Replicate or distribute across accounts replicate scan scope Which baskets are scanned, with which styles/sides Best stocks, MyChoice, MyLongTerm data.csv import.default profile Column mapping for your CSV files my 1min files live.max ws instruments Cap on live-streamed instruments (active set) 200 portfolio.min days for xirr Below this, show absolute return instead of XIRR 30 selection.min p win / min exp R lower Trade quality bar 0.45 / +0.10R learning.min trades Evidence needed per cell 30 goals.max drawdown pct Halt-and-review threshold 8%"},{"d":16,"h":"17 — Deployment & Operations (Podman, local-only)","a":"","t":"Everything runs in Podman containers on your Mac. No cloud service is required; internet is used only for broker/exchange APIs."},{"d":16,"h":"1. Podman machine","a":"1-podman-machine","t":"- Containers run in a Linux VM (Podman machine). Use the libkrun provider on Apple Silicon — it gives containers GPU acceleration (Vulkan), which xd-llm needs. - Size: 10 CPUs, 24 GB RAM, 120 GB disk (decision Q8; confirmed by the xd-llm benchmark in P0-15, 2026-10-10: with the 30B model loaded and the stack running the VM peaked at 5.3 GB because model weights live in GPU memory). Revisit the disk before tick-data storage (P13). - Static IP (decision Q6): not needed until automated orders (P12) — see §6. - The host Mac (48 GB) is already swapping heavily (28–42 GB of macOS swap in use in the sampled P0-15 runs); a resident 30B model adds ≈ 20 GB of GPU memory and loaded in 22–105 s (cause not established). xd-llm is therefore started on demand (ADR 0005). - Disk budget: VM disk 120 GB (originally planned 250 GB) holds the images, databases and, if used, the 18.6 GB model volume; revisit before tick data (P13). - Source code: local git only (decision Q7) — no remote yet. Keep a copy outside the Mac's internal disk (Time Machine or the external SSD) until a remote is chosen; xd-backup protects data, not code. - The Mac must be awake for nightly jobs (and during market hours for later live services): no sleep on power, wired network, small UPS recommended."},{"d":16,"h":"2. Containers","a":"2-containers","t":"Container Image basis Profile Notes xd-proxy Caddy (+ React build) core Only published HTTP port (127.0.0.1:8080 until login/TLS, then LAN); routes /api, /health (later /hubs, /hangfire); serves the docs read-only at /prototype/ (clickable prototype, delivery plan at /prototype/delivery/) and /docs/ (design-docs site); compression, security headers xd-migrate API image, migrate core One-shot: applies migrations, then exits xd-api .NET 10 ASP.NET Core core REST, SignalR, auth, assistant endpoint xd-worker .NET 10 + Hangfire core CSV import (watches data/inbox), EOD fetch, aggregation, account & portfolio sync, nightly pipeline, backtests, Lab runs, ML.NET training; scale replicas xd-feed .NET 10 core Market hours: Dhan WebSocket for the active set, quote polling for holdings, live bars & alerts (later also depth recording) xd-sandbox .NET 10 worker core User C plugins; no network , read-only data, CPU/memory/time limits xd-db PostgreSQL + TimescaleDB (official image) core Named volume; read-only role for tools xd-seq Seq ops Logs xd-backup restic + pg dump ops Nightly encrypted backup to external SSD xd-llm llama.cpp server (pinned RamaLama image) ai GPU via libkrun (/dev/dri); model from the host folder or the volume xd-models (decide in P9-01); no published port; on demand xd-mcp .NET 10 ai Read-only MCP tools xd-hermes Own image, pinned Hermes Agent ai (optional) Only after PoC; hardened (doc 14) xd-exec .NET 10 live (later) Orders; isolated network; only holder of order-capable tokens Defined in deploy/compose.yaml with profiles core, ops, ai, live (podman compose --profile core --profile ops up -d). Podman Desktop shows them as one application."},{"d":16,"h":"3. Networks","a":"3-networks","t":"Network Members front proxy, api back (internal) api, worker, sandbox , db, llm, mcp, seq, feed exec (internal) exec, db Egress allowed worker, feed, exec (broker/exchange hosts only) xd-sandbox has no egress and no access except its job inputs/outputs."},{"d":16,"h":"4. Secrets","a":"4-secrets","t":"1. Source of truth: macOS Keychain (xdrishti/<area /<name : broker API keys/secrets per account, DB passwords, backup key). 2. deploy/xd-up.sh reads the Keychain (creating strong random DB passwords on first run) → writes secret files to /Library/Application Support/xDrishti/secrets (private folder) → Compose mounts them as file secrets (ADR 0003). 3. Containers receive only what they need (mounted at /run/secrets/<ConfigKey , read by .NET KeyPerFile provider). 4. Never in images, compose files, environment dumps, logs or LLM context."},{"d":16,"h":"5. Operations","a":"5-operations","t":"Topic Approach Start at boot launchd agent → podman machine start → xd-up.sh; services run with no user logged in to the app Missed schedules On start, services catch up missed runs (e.g. EOD fetch while the Mac slept) and reconcile desired state Schedules Stored in the database (ops.service schedules), edited on the Services screen with dependency validation; applied to Hangfire recurring jobs in xd-worker without restart Database migrations EF Core migrations applied by the one-shot xd-migrate service (API image, migrate command, as xd owner) before xd-api/xd-worker start; apps connect as least-privilege xd app Start / stop deploy/xd-up.sh (secrets → build → start → wait healthy → print URLs), deploy/xd-down.sh (--purge deletes data) URLs (local) App http://localhost:8080 · API docs /api/docs · Seq http://localhost:5341 · PostgreSQL localhost:5433 (dev override) Upgrades Versioned image tags; roll back by switching tag Backups Nightly pg dump + models + config → restic on external SSD; monthly restore test Health ASP.NET health checks per container; failures → in-app notification Logs Serilog → Seq; container log rotation Disk Timescale compression; tick data (later) 50–100 GB/year → external SSD volume CSV inbox Host folder data/inbox/ bind-mounted into xd-worker; processed files moved to data/processed/<job-id / Market hours xd-feed starts 09:00 and stops 15:35 on trading days (scheduled); Mac must be awake Remote access Off by default; optional WireGuard on home router Dev loop dotnet watch and Vite dev server on the host against containerised db/llm/ml; same images for \"prod\""},{"d":16,"h":"6. Costs","a":"6-costs","t":"Item Cost Podman Desktop, .NET, React, PostgreSQL/TimescaleDB, Caddy, Seq (single user), LLM runtime & models ₹0 Dhan Data API (one account) ≈ ₹590/month incl. GST NSE files (optional reconciliation) ₹0 External SSD + UPS (one-time, recommended) ≈ ₹10–18k ISP static IP Only when automated orders are enabled (P12); decision Q6: later, revisit at the P11 exit Cloud ₹0 — none used"},{"d":17,"h":"18 — Roadmap","a":"","t":"Part-time ( 10–12 h/week) with an AI coding assistant. Each phase ends with an exit criterion. Portfolio monitoring comes early because it is useful on its own while the trading engine is being built. Phase Deliverables Exit criterion P0 Foundations (2w) Answer open questions (doc 01 §5); review the clickable prototype (docs/prototype/); Podman machine (libkrun); repo skeleton: .NET solution, React (Vite) app, compose.yaml with xd-db; Keychain→secrets script; Dhan trial (Data API, API key/secret token flow, 1-minute history for 20 symbols); CSV profile for your files + sample import; xd-llm GPU benchmark; ML.NET spike on linux/arm64 Data-quality note written; stack starts with one command P1 Data platform & instruments (5w) Dhan adapter (instrument master, history, accounts); CSV import (profiles, preview, validation, upsert, undo, folder watch, CLI); Timescale hypertables + continuous aggregates (5m…1h, 1D/1W/1M); corporate actions; calendar; context data; master list, tracked instruments, baskets (manual, rule-based, system); EOD fetch + backfill jobs; quality checks; Data quality window (validation service, stored-vs-recomputed aggregates, repair); React shell with login (password; re-entry for sensitive actions), Accounts (list/detail tabs, role matrix, risk profiles, wizard), Services screen with schedule configuration & dependency checks , Instruments, Baskets and Data/Import screens; commands/desired-state + audit Your CSV history imported; 5 unattended EOD fetches; all timeframes match a hand-check on 10 samples P2 Portfolio monitor & live feed (4w) Account sync (holdings, positions, trade history, ledger); transactions, FIFO lots, positions, buckets; CSV/manual trade import; XIRR , returns, benchmark; daily valuations; xd-feed live feed for the active set + quote polling for holdings; Portfolio screen (per-account tiles, Action center , price alerts, group by bucket/basket/account/sector, tree-grid, charts) Portfolio values and XIRR match a spreadsheet check for 3 accounts/buckets; live P&L updates during market hours P3 Simulator, DSL & first strategies (5w) Streaming indicators/features; DSL parser → expression trees + look-ahead lint; event-driven simulator (conditional entries, stops, square-off, max hold, gaps, costs, slippage, MAE/MFE); ORB, VWAP PULLBACK, BASE BREAKOUT; scans scoped by basket 20 random trades hand-verified against charts P4 Exits & exit learning (3w) All exit policies incl. pyramiding; same-entries comparison; per-cell exit choice (walk-forward); MAE/MFE diagnostics Chosen exits stable across folds P5 Strategy Lab v1 (3w) Lab API + Hangfire runs + SignalR progress; verdict & report; test ledger; xd CLI; Strategy Lab page (Monaco + schema); basket as test universe; xd-sandbox for C plugins 3 of your own ideas tested end-to-end without code changes P6 Learning engine & ML.NET model (5w) Regime labels; cell stats (Bayesian, recency); triple-barrier labels; ML.NET LightGBM/FastTree + PAV calibration + feature contributions; model registry; drift, lifecycle, changelog, hypothesis loop; lessons (monitors → problem/fix/result), experiments (tweak & re-run replay with honest comparison rules), frozen-model counterfactual; meta-labelling model, learned entry windows, automatic loss tags ; remaining strategies Meta-model beats baselines OOS; calibration error ≤ 5 pp; a knob change can be replayed and compared in < 10 min P7 Selection, accounts & nightly plan (3w) Filters, merge, ranking, portfolio fill; per-account allocation (Trading-role accounts); plan review & approval workflow with pre-trade checklist, suggestions inbox, review cutoff ; auto-journal; grading (primary/reserve/rejected); pre-open check; autonomy levels with auto-approval at the cutoff ; smart rules in the nightly plan (market gate, equity-curve throttle, correlation-aware selection); weekly learning digest ; fail-closed nightly pipeline; plan tickets join the live active set; start depth recording Plans published 10 consecutive sessio"},{"d":18,"h":"1. Research risks","a":"1-research-risks","t":"Pitfall Countermeasure Overfitting Walk-forward OOS only, ≤ 4 params, plateaus, min samples, paper stage Multiple-testing luck Test ledger, deflated thresholds, consistency across folds/years Look-ahead bias Closed-bar-only DSL, point-in-time features, single code path, automated tests Survivorship bias Historical constituents incl. delisted stocks Intrabar ambiguity Resolve on 1-minute path; if still ambiguous assume the worse outcome Unrealistic fills Gap fills at open, slippage model, no fills at locked circuits Cost blindness Costs in every simulation; max cost R filter Regime dependence Regime-conditioned stats, drift monitor, auto-pause ML leakage Purged & embargoed walk-forward"},{"d":18,"h":"2. Market risks","a":"2-market-risks","t":"Risk Countermeasure Overnight gaps (swing) Heat cap, event exits, max hold ≤ 5 sessions Correlated losses Sector/correlation limits, net exposure caps Liquidity/slippage Turnover filters; live slippage measured Extreme days Daily loss limit, gap/VIX filter, max-drawdown halt Short constraints Swing shorts via futures only F&O ban, surveillance, margin changes Nightly exclusion filters"},{"d":18,"h":"3. Behavioural risks","a":"3-behavioural-risks","t":"Risk Countermeasure Skipping/adding trades Auto-journal + discipline report quantifies deviations Tweaking after every loss Changes only via hypothesis loop; versioned config Over-trusting LLM prose Numbers only from tools; LLM never decides trades Scaling too early Paper ≥ 12 weeks, then reduced-size live"},{"d":18,"h":"4. Operational risks","a":"4-operational-risks","t":"Risk Countermeasure Bad data → wrong plan Quality gates; fail closed Misconfigured schedules (e.g. pre-open before cutoff, nightly before data) Dependency & timing rules block invalid schedules; timeline view; catch-up Automation over-reach (system changes too much on its own) Autonomy levels; weekly cap on automatic changes; always-ask list (risk increases, new strategies, live execution, accounts); change log with revert; automatic rollback after 60-trade monitoring Overfitting through repeated experiments Required improvement rises with trials (multiple-testing guard); 12 OOS folds; judged after live gap and on total R; shadow before apply Smart rules filtering too much (e.g. too many no-trade days) or learned on noise Evidence shown per rule; review flag when a rule removes 50% of trades or its skipped trades are not worse than taken ones; rules learned from walk-forward data, not only live trades Learning from plan prices that cannot be achieved Grade on actual fills; slippage model per liquidity bucket; capacity score Alert fatigue (too many action items) Smarter thresholds (relative to account size), severity filter, snooze/done, per-account focus Plan not reviewed in time Unreviewed tickets lapse (safe default); reminders before cutoff; phone review via PWA Account role misconfiguration (no data account, wrong trading account) Validation rules (exactly one primary Data account), password re-entry, audit, Services screen warnings Unauthorised access Login (strong password), lockout, idle timeout, LAN-only, audit of logins CSV import errors (wrong timezone, bar-end labels, adjusted vs raw prices, duplicates) Import profiles, preview before commit, session-boundary checks, conflict log, undo per import job Live-feed overload or disconnects Live data only for the active set (cap max ws instruments); auto-reconnect; EOD official data replaces live bars Incomplete portfolio history (API history window, other brokers) CSV/manual transaction import; reconciliation of computed vs broker holdings each night Misleading XIRR on short holdings Absolute return below min days for xirr; XIRR flagged \"short period\" Silent job failure Hangfire retries + in-app notification + Seq alerts Data loss Nightly restic backups; monthly restore test Secret leakage Keychain → Podman secrets; never in config/logs/LLM Broker API changes / token expiry Adapter isolation, retries, fallback provider, token status on Accounts screen Mac asleep/offline Power settings, UPS, wired network; broker-side stops once execution exists VM disk/memory exhaustion Machine sizing, Timescale compression, disk alerts, external SSD for ticks Runaway automated orders (later) Pre-trade checks, ≤ 2 orders/s, idempotency, kill switch, reconciliation freeze Third-party agent vulnerabilities (Hermes) Optional only; hardened container; pinned version; CVE checks"},{"d":18,"h":"5. Compliance (India)","a":"5-compliance-india","t":"- Personal use only : one user, own accounts. Sharing or selling recommendations could require SEBI Research Analyst / Investment Adviser registration — out of scope by design. - SEBI retail algo framework (mandatory since 1 April 2026) applies when orders are placed via broker APIs: registered app on a whitelisted static IP , daily login/2FA, broker as principal. Own strategies staying ≤ 10 orders/second per exchange are tagged with the broker's generic algo ID; above that, exchange approval is needed. v1 places no orders; Phase 12 caps at 2 orders/s. Re-check circulars before Phase 12. Static-IP decision (Q6, 2026-10-09): not needed until Phase 12; ask the ISP and re-check circulars at the P11 exit. - Data APIs used within the broker's terms. - Forex/CFD trading via offshore platforms (e.g. MT5 brokers) is not part of this system."},{"d":18,"h":"6. Expectations","a":"6-expectations","t":"Good systematic setups typically show 40–60% win rates and +0.1R to +0.4R expectancy after costs. Backtests showing 80% wins and +1R/trade are almost certainly overfit or leaking. Losing weeks and multi-week drawdowns are normal; the Monte Carlo report shows what to expect. The value is consistency, risk control and learning from evidence."},{"d":19,"h":"20 — Extended Modules (later phases)","a":"","t":"Designed now so v1 leaves room for them; built after v1 is proven. Module Phase Container / project A. Automated order placement P12 xd-exec / XDrishti.Execution B. Tick & order-book data Recorder from P7, features P13 xd-feed / XDrishti.Feed C. Options & statistical arbitrage P14 Engine modules D. Fundamentals & events P15 Worker jobs + assistant extraction HFT / latency arbitrage Not pursued —"},{"d":19,"h":"A. Automated order placement","a":"a-automated-order-placement","t":"Modes per account: paper → manual live → assisted (system prepares exact order / super-order parameters) → semi auto (one-tap confirm in UI) → auto live (within hard limits, every action notified). - Broker-side stop first — protection never depends on the Mac staying up. - Pre-trade checks: same limits as planning + price band vs LTP, freeze quantity, margin. - Idempotent client order ids; order-update stream + end-of-day reconciliation; mismatch ⇒ freeze. - Kill switch: ours (stop new, cancel pending, optional exit-all) + broker's where available; triggered by max drawdown, daily loss, feed loss or a button. - Prerequisites: ISP static IP whitelisted at Dhan; daily login/2FA; ≤ 2 orders/s; Dhan sandbox testing first."},{"d":19,"h":"B. Tick & order-book data","a":"b-tick-order-book-data","t":"- Dhan live feed + 20-level depth (up to 50 instruments/connection) and 200-level depth (NSE equity & derivatives) over WebSocket (binary). No historical depth from brokers ⇒ record our own. - Extends the v1 xd-feed (which already streams the active set): adds 20-level depth subscriptions for a configured recording list; writes to Timescale hypertables (compressed); 50–100 GB/year. - Start recording in P7 so ≥ 6 months exist by P13. - Uses: order-book imbalance, depth pressure near trigger, aggressive volume delta, spread → meta-model features and realistic slippage. Kept only if OOS improves. - HFT/latency arbitrage not pursued: home latency vs co-located firms, order-rate limits and costs leave no retail edge."},{"d":19,"h":"C. Options & statistical arbitrage","a":"c-options-statistical-arbitrage","t":"- Data: Dhan option chain API (OI, Greeks, IV, bid/ask; 1 request / 3 s per underlying-expiry) and expired options data API for backtests; own chain snapshots (5-min for indices, EOD for stocks). - Families: directional expression (ITM/ATM options for our signals), defined-risk debit spreads (swing), index credit spreads / iron condors in range regimes, event/IV-aware positioning. - New learning dimension instrument expression (cash / future / option buy / debit spread …). - Simulation from historical option prices; Black-Scholes with recorded IV only as fallback; premium and underlying-based exits; exit before expiry by default; liquidity filters (index options first). - \"Slow\" statistical arbitrage: PAIRS (cointegration mean reversion) and BASIS (cash-futures) on 5m+ bars — two-leg, so practical with module A."},{"d":19,"h":"D. Fundamentals & events","a":"d-fundamentals-events","t":"- Data: exchange filings (results XBRL/PDF), shareholding (promoter holding, pledges), announcements, results calendar — stored point-in-time by filing timestamp . - Uses: swing universe quality filter; features (growth, margin trend, surprise vs last 4 quarters, valuation percentile); PEAD (post-earnings drift) swing family; event-risk filter. - Assistant extracts structured fields from PDFs/announcements, validated against XBRL; outputs are features measured like any other, never trade decisions."},{"d":20,"h":"21 — Glossary","a":"","t":"Term Meaning Account role What an account is used for: Data, Trading, Portfolio (one account can have several) Action center List of portfolio positions needing a decision, generated by rules per account Active set Instruments streamed live: open positions, armed tickets, context indices, pinned baskets Approval Your decision on a proposed ticket or suggestion: approve, modify or reject Armed ticket Approved ticket that passed the pre-open check and is being watched live ATR Average True Range — average bar range; scales stops/targets to volatility Auto-approval Ticket approved by the pre-open service at the cutoff because it meets your autonomy rule (P(win) threshold and every check passing) Autonomy level How much the system decides alone: advisory, supervised (default) or autonomous within limits Basket Named group of tracked instruments (manual, rule-based or system); an instrument can be in many Bias timeframe Higher timeframe deciding the allowed direction for a lower-timeframe entry Bucket (portfolio) Exclusive grouping of positions so portfolio totals add up CAGR Compound annual growth rate Calibration Adjusting model scores so predicted probabilities match observed frequencies Capacity score How reliably a cell's tickets actually get filled (partial fills, rejections, missed triggers); used in selection Cell (setup cell) Unit of learning: strategy × timeframe × side × style × exit policy × regime Champion / challenger Current model/parameters vs a candidate running in shadow until proven better Common random numbers Replaying candidate and current settings on the same trades/days so only the change differs Conditional ticket Trade defined by trigger, validity window, stop, exit, size — executed only if triggered Confluence Several strategies/timeframes agreeing on the same symbol and side Continuous aggregate TimescaleDB materialised view that keeps derived bars (5m, 15m…) up to date Control plane The UI/API where you record what you want; services do the work CPR Central Pivot Range from the previous day's high/low/close Data quality score Share of tracked instruments passing validation (warnings count half) Deflated Sharpe Sharpe ratio adjusted for the number of strategies tried Drift Live/paper performance moving away from backtest expectations DSL The strategy rules language used by built-ins and the Strategy Lab Embargo / purge Removing overlap between train and test data to prevent leakage Entry window (learned) Best entry hour for a setup from walk-forward results; used as the ticket's validity window Equity-curve throttle Risk is cut (default × 0.5) while the system's own equity is below its N-trade average Execution gap Difference between results at plan prices and at actual fills (slippage, missed triggers, overrides, charges) Expectancy (E[R]) Average result per trade in R after costs Experiment (replay) Changing a learning knob and re-running walk-forward to compare with the current model before anything goes live Fail closed On error, produce no plan rather than a possibly wrong one Failover (data) Automatic switch to the standby Data account when the primary fails FIFO lots Sells consume the oldest buys first; basis for realised P&L Frozen-model counterfactual What a copy of last year's model would have done on the same days — the baseline for measuring learning progress Graded on fills Results computed from executed prices, not plan prices; plan-price R is kept to measure the execution gap Hangfire .NET background-job library (schedules, retries) using PostgreSQL storage Heat Sum of open risk across positions as % of capital Import profile Saved column mapping for a CSV file format Lapsed A proposed ticket not reviewed before the cutoff — never armed Learning health 0–100 score from data quality, calibration, execution, stability and evidence Lens How results are grouped: all trades, by basket, by instrument, by trade, by strategy, by account Lesson Record of a detected problem: what went wrong → diagno"},{"d":20,"h":"Further reading","a":"further-reading","t":"- Van K. Tharp — Trade Your Way to Financial Freedom (R-multiples, expectancy, sizing) - Marcos López de Prado — Advances in Financial Machine Learning (triple barrier, meta-labeling, purged CV) - Kevin Davey — Building Winning Algorithmic Trading Systems (walk-forward, Monte Carlo, incubation)"}],"glossary":[{"term":"Account role","alts":["Account role"],"def":"What an account is used for: Data, Trading, Portfolio (one account can have several)"},{"term":"Action center","alts":["Action center"],"def":"List of portfolio positions needing a decision, generated by rules per account"},{"term":"Active set","alts":["Active set"],"def":"Instruments streamed live: open positions, armed tickets, context indices, pinned baskets"},{"term":"Approval","alts":["Approval"],"def":"Your decision on a proposed ticket or suggestion: approve, modify or reject"},{"term":"Armed ticket","alts":["Armed ticket"],"def":"Approved ticket that passed the pre-open check and is being watched live"},{"term":"ATR","alts":["ATR"],"def":"Average True Range — average bar range; scales stops/targets to volatility"},{"term":"Auto-approval","alts":["Auto-approval"],"def":"Ticket approved by the pre-open service at the cutoff because it meets your autonomy rule (P(win) threshold and every check passing)"},{"term":"Autonomy level","alts":["Autonomy level"],"def":"How much the system decides alone: advisory, supervised (default) or autonomous within limits"},{"term":"Basket","alts":["Basket"],"def":"Named group of tracked instruments (manual, rule-based or system); an instrument can be in many"},{"term":"Bias timeframe","alts":["Bias timeframe"],"def":"Higher timeframe deciding the allowed direction for a lower-timeframe entry"},{"term":"Bucket (portfolio)","alts":["Bucket","portfolio"],"def":"Exclusive grouping of positions so portfolio totals add up"},{"term":"CAGR","alts":["CAGR"],"def":"Compound annual growth rate"},{"term":"Calibration","alts":["Calibration"],"def":"Adjusting model scores so predicted probabilities match observed frequencies"},{"term":"Capacity score","alts":["Capacity score"],"def":"How reliably a cell's tickets actually get filled (partial fills, rejections, missed triggers); used in selection"},{"term":"Cell (setup cell)","alts":["Cell","setup cell"],"def":"Unit of learning: strategy × timeframe × side × style × exit policy × regime"},{"term":"Champion / challenger","alts":["Champion","challenger"],"def":"Current model/parameters vs a candidate running in shadow until proven better"},{"term":"Common random numbers","alts":["Common random numbers"],"def":"Replaying candidate and current settings on the same trades/days so only the change differs"},{"term":"Conditional ticket","alts":["Conditional ticket"],"def":"Trade defined by trigger, validity window, stop, exit, size — executed only if triggered"},{"term":"Confluence","alts":["Confluence"],"def":"Several strategies/timeframes agreeing on the same symbol and side"},{"term":"Continuous aggregate","alts":["Continuous aggregate"],"def":"TimescaleDB materialised view that keeps derived bars (5m, 15m…) up to date"},{"term":"Control plane","alts":["Control plane"],"def":"The UI/API where you record what you want; services do the work"},{"term":"CPR","alts":["CPR"],"def":"Central Pivot Range from the previous day's high/low/close"},{"term":"Data quality score","alts":["Data quality score"],"def":"Share of tracked instruments passing validation (warnings count half)"},{"term":"Deflated Sharpe","alts":["Deflated Sharpe"],"def":"Sharpe ratio adjusted for the number of strategies tried"},{"term":"Drift","alts":["Drift"],"def":"Live/paper performance moving away from backtest expectations"},{"term":"DSL","alts":["DSL"],"def":"The strategy rules language used by built-ins and the Strategy Lab"},{"term":"Embargo / purge","alts":["Embargo","purge"],"def":"Removing overlap between train and test data to prevent leakage"},{"term":"Entry window (learned)","alts":["Entry window","learned"],"def":"Best entry hour for a setup from walk-forward results; used as the ticket's validity window"},{"term":"Equity-curve throttle","alts":["Equity-curve throttle"],"def":"Risk is cut (default × 0.5) while the system's own equity is below its N-trade average"},{"term":"Execution gap","alts":["Execution gap"],"def":"Difference between results at plan prices and at actual fills (slippage, missed triggers, overrides, charges)"},{"term":"Expectancy (E[R])","alts":["Expectancy"],"def":"Average result per trade in R after costs"},{"term":"Experiment (replay)","alts":["Experiment","replay"],"def":"Changing a learning knob and re-running walk-forward to compare with the current model before anything goes live"},{"term":"Fail closed","alts":["Fail closed"],"def":"On error, produce no plan rather than a possibly wrong one"},{"term":"Failover (data)","alts":["Failover","data"],"def":"Automatic switch to the standby Data account when the primary fails"},{"term":"FIFO lots","alts":["FIFO lots"],"def":"Sells consume the oldest buys first; basis for realised P&L"},{"term":"Frozen-model counterfactual","alts":["Frozen-model counterfactual"],"def":"What a copy of last year's model would have done on the same days — the baseline for measuring learning progress"},{"term":"Graded on fills","alts":["Graded on fills"],"def":"Results computed from executed prices, not plan prices; plan-price R is kept to measure the execution gap"},{"term":"Hangfire","alts":["Hangfire"],"def":".NET background-job library (schedules, retries) using PostgreSQL storage"},{"term":"Heat","alts":["Heat"],"def":"Sum of open risk across positions as % of capital"},{"term":"Import profile","alts":["Import profile"],"def":"Saved column mapping for a CSV file format"},{"term":"Lapsed","alts":["Lapsed"],"def":"A proposed ticket not reviewed before the cutoff — never armed"},{"term":"Learning health","alts":["Learning health"],"def":"0–100 score from data quality, calibration, execution, stability and evidence"},{"term":"Lens","alts":["Lens"],"def":"How results are grouped: all trades, by basket, by instrument, by trade, by strategy, by account"},{"term":"Lesson","alts":["Lesson"],"def":"Record of a detected problem: what went wrong → diagnosis → fix → result, with revert"},{"term":"Loss tag","alts":["Loss tag"],"def":"Automatic reason attached to a losing trade (gap through stop, gave back open profit, against regime, …)"},{"term":"MAE / MFE","alts":["MAE","MFE"],"def":"Maximum adverse / favourable excursion during a trade"},{"term":"Market gate","alts":["Market gate"],"def":"Learned rule deciding whether tomorrow is a normal, reduced or no-trade day (VIX, breadth, events)"},{"term":"Master list","alts":["Master list"],"def":"All instruments from Dhan's instrument master"},{"term":"MCP","alts":["MCP"],"def":"Model Context Protocol — standard way to expose tools to an LLM"},{"term":"Meta-labeling","alts":["Meta-labeling"],"def":"ML deciding whether to take a trade proposed by a rule strategy"},{"term":"Meta-labelling","alts":["Meta-labelling"],"def":"A second model that decides whether to take a signal and how big, trained on your graded trades"},{"term":"MIS / CNC","alts":["MIS","CNC"],"def":"Intraday margin / delivery product types (Indian brokers)"},{"term":"ML.NET","alts":["ML.NET"],"def":"Microsoft's machine-learning library for .NET; trains and scores our models in-process"},{"term":"NR7","alts":["NR7"],"def":"Narrowest range of the last 7 bars"},{"term":"OOS","alts":["OOS"],"def":"Out-of-sample — data not used for fitting"},{"term":"ORB","alts":["ORB"],"def":"Opening Range Breakout"},{"term":"Paper trading","alts":["Paper trading"],"def":"Following the system without real money to validate it"},{"term":"PAV calibration","alts":["PAV calibration"],"def":"Pool-Adjacent-Violators — isotonic calibration of model probabilities"},{"term":"Pivot builder","alts":["Pivot builder"],"def":"Report that crosses any two dimensions with a chosen metric"},{"term":"Pre-trade checklist","alts":["Pre-trade checklist"],"def":"Automatic checks shown on each proposed ticket before you approve"},{"term":"Profit factor","alts":["Profit factor"],"def":"Gross profit / gross loss"},{"term":"Pyramiding","alts":["Pyramiding"],"def":"Adding to a winner at set levels while capping total risk at the initial 1R"},{"term":"R / R-multiple","alts":["R-multiple"],"def":"Result divided by initial risk"},{"term":"Regime","alts":["Regime"],"def":"Market state (trend × volatility) used to condition statistics"},{"term":"Reserve list","alts":["Reserve list"],"def":"Next-best tickets used if a primary is invalidated"},{"term":"Rollback (automatic)","alts":["Rollback","automatic"],"def":"Undoing an applied learning change when live results over the monitoring window fall below the previous version"},{"term":"Run-after chain","alts":["Run-after chain"],"def":"A service scheduled to run when another service finishes successfully"},{"term":"Same bet","alts":["Same bet"],"def":"Two tickets or positions whose 60-day returns are correlated above the limit; the weaker one goes to reserve"},{"term":"Service identity","alts":["Service identity"],"def":"Background services act as the system, not as a logged-in user"},{"term":"Square-off","alts":["Square-off"],"def":"Closing an intraday position before session end"},{"term":"Step-up auth","alts":["Step-up auth"],"def":"Password re-entry before sensitive actions (role, credential, risk and autonomy changes)"},{"term":"Stored vs recomputed","alts":["Stored vs recomputed"],"def":"Validation comparing saved aggregate bars with bars rebuilt from 1-minute data"},{"term":"Suggestions inbox","alts":["Suggestions inbox"],"def":"AI/engine proposals awaiting your accept/reject"},{"term":"Time stop","alts":["Time stop"],"def":"Exit if no progress within N bars/sessions"},{"term":"Tracked instrument","alts":["Tracked instrument"],"def":"Instrument you've switched on for data collection, scans and analytics"},{"term":"Triple barrier","alts":["Triple barrier"],"def":"Labelling by which is hit first: target, stop or time limit"},{"term":"VWAP","alts":["VWAP"],"def":"Volume-weighted average price of the session"},{"term":"Walk-forward","alts":["Walk-forward"],"def":"Repeated train-on-past / test-on-next-period evaluation"},{"term":"Weekly learning digest","alts":["Weekly learning digest"],"def":"Weekly summary of progress vs the frozen model, automatic changes, items needing you and loss causes"},{"term":"XIRR","alts":["XIRR"],"def":"Annualised return computed from dated cash flows (buys, sells, dividends, current value)"}]};
